-- =============================================================================
-- 540 — LE CAHIER D'EXERCICES DE 1RE (partie 28)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 540 --niveau 1re --fichiers maths.n1,maths.n2,maths.n3,musique.jumelles --suffixe 28 > supabase/contenu/540_exercices_1re_28.sql
--
-- 84 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   maths.n1                27 exercices · 9 chapitres
--   maths.n2                27 exercices · 9 chapitres
--   maths.n3                21 exercices · 7 chapitres
--   musique.jumelles         9 exercices · 3 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('fbef6f22-850c-5e27-9bd0-ee37f32d82f4'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les premiers termes de Léa","competence":"lire-tableau","situation":"Léa étudie la suite (u) définie pour tout entier n par u(n) = n² + 1. Elle a recopié ses premiers termes dans un tableau, mais il reste une case à remplir.","documents":[{"id":"termes","type":"tableau","titre":"Les termes de la suite (u)","colonnes":["Rang n","0","1","2","3","4","5"],"lignes":[["u(n)",1,2,5,10,17,"?"]],"enteteLignes":true,"source":"Valeurs calculées pour l’exercice"}],"questions":[{"enonce":"Touche dans le tableau le terme de rang 3, noté u(3).","aide":"Repère la colonne dont le rang n vaut 3, puis descends à la ligne de u(n).","type":"zone","document":"termes","multiple":false},{"enonce":"Calcule le terme manquant u(5).","aide":"Remplace n par 5 dans la formule n² + 1.","type":"nombre"},{"enonce":"Sans calculer les termes précédents, donne u(10).","aide":"Avec une formule explicite, on remplace directement n par 10.","type":"nombre"},{"enonce":"Au vu du tableau, comment semble évoluer la suite ?","aide":"Compare chaque terme au précédent : 1, 2, 5, 10, 17…","type":"choix","options":[{"id":"a","texte":"Elle semble constante"},{"id":"b","texte":"Elle semble décroissante"},{"id":"c","texte":"Elle semble croissante"},{"id":"d","texte":"Elle alterne : un terme monte, le suivant descend"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c4"]},"explication":"Le terme de rang 3 est dans la colonne **n = 3** : u(3) = **10**."},{"cle":{"type":"nombre","valeur":26,"tolerance":0},"affichage":"26","explication":"u(5) = 5² + 1 = 25 + 1 = **26**."},{"cle":{"type":"nombre","valeur":101,"tolerance":0},"affichage":"101","explication":"Une définition explicite permet d’aller droit au but : u(10) = 10² + 1 = **101**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Chaque terme est plus grand que le précédent : la suite **semble croissante** (on le démontre avec le signe de u(n+1) − u(n))."}]$ex$::jsonb),
  ('fbef6f22-850c-5e27-9bd0-ee37f32d82f4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un creux au rang 3","competence":"lire-graphique","situation":"Au tableau, le professeur trace le diagramme en bâtons de la suite (u) définie par u(n) = (n − 3)². Chaque bâton représente un terme, pour n allant de 0 à 6.","documents":[{"id":"batons","type":"graphique","forme":"barres","titre":"Les termes de (u) pour n de 0 à 6","categories":["0","1","2","3","4","5","6"],"series":[{"nom":"u(n)","valeurs":[9,4,1,0,1,4,9],"teinte":"violet"}],"axeY":{"titre":"u(n)","min":0,"max":10,"pas":2},"axeX":{"titre":"Rang n"},"valeurs":false,"source":"Valeurs calculées pour l’exercice"}],"questions":[{"enonce":"Touche le terme le plus petit de la suite.","aide":"Cherche le bâton le plus court.","type":"zone","document":"batons","multiple":false},{"enonce":"La suite est-elle monotone (toujours croissante, ou toujours décroissante) ?","aide":"Regarde les bâtons de gauche à droite : montent-ils tous ?","type":"choix","options":[{"id":"a","texte":"Oui : elle est croissante"},{"id":"b","texte":"Non : elle baisse puis monte"},{"id":"c","texte":"Non : elle est constante"},{"id":"d","texte":"Oui : elle est décroissante"}],"multiple":false},{"enonce":"Calcule u(7) avec la formule u(n) = (n − 3)².","aide":"Remplace n par 7 puis élève au carré.","type":"nombre"},{"enonce":"À partir de quel rang n a-t-on u(n+1) > u(n) pour tous les rangs suivants ? On rappelle que u(n+1) − u(n) = 2n − 5.","aide":"Cherche le premier entier n pour lequel 2n − 5 est strictement positif.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Le plus petit terme est u(3) = (3 − 3)² = **0**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les bâtons **baissent** de n = 0 à n = 3, puis **montent** : la suite n’est ni croissante ni décroissante sur tous les rangs."},{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16","explication":"u(7) = (7 − 3)² = 4² = **16**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"Pour n = 2, 2n − 5 = −1 < 0 ; pour n = 3, 2n − 5 = 1 > 0, et ensuite c’est toujours positif. La suite croît strictement à partir du rang **3**."}]$ex$::jsonb),
  ('fbef6f22-850c-5e27-9bd0-ee37f32d82f4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une suite qui s’emballe","competence":"raisonner","situation":"Camille étudie la suite (u) définie par récurrence. Elle calcule les premiers termes à la main, remplit un tableau, puis propose une formule pour aller plus vite.","documents":[{"id":"consigne","type":"texte","genre":"consigne","titre":"Définition de la suite","blocs":["Suite (u) : u(0) = 2 et, pour tout entier n, u(n+1) = 3 × u(n) − 2."],"source":"Texte écrit pour l’exercice"},{"id":"termes","type":"tableau","titre":"Les premiers termes de (u)","colonnes":["Rang n","0","1","2","3","4"],"lignes":[["u(n)",2,4,10,"?","?"]],"enteteLignes":true}],"questions":[{"enonce":"Calcule u(3) avec la relation de récurrence.","aide":"Multiplie u(2) par 3 puis retire 2.","type":"nombre"},{"enonce":"Calcule u(4).","aide":"Pars du terme que tu viens de trouver.","type":"nombre"},{"enonce":"Calcule u(5).","aide":"Même geste, à partir de u(4).","type":"nombre"},{"enonce":"Camille propose la formule explicite u(n) = 3ⁿ + 1. Elle vérifie qu’elle donne bien u(0), u(1), …, u(5). Que peut-on en conclure ?","aide":"Six vérifications couvrent-elles tous les entiers ?","type":"choix","options":[{"id":"a","texte":"Elle colle aux six premiers termes, mais il faudrait le démontrer pour tout n"},{"id":"b","texte":"Elle est fausse, une récurrence n’a jamais de formule explicite"},{"id":"c","texte":"Elle est fausse dès u(2)"},{"id":"d","texte":"Elle est démontrée : six termes exacts suffisent"}],"multiple":false},{"enonce":"On calcule u(n+1) − u(n) = 2 × u(n) − 2. Sachant que tous les termes sont supérieurs ou égaux à 2, que dire du sens de variation ?","aide":"Si u(n) ≥ 2, que vaut 2 × u(n) − 2 au minimum ?","type":"choix","options":[{"id":"a","texte":"u(n+1) − u(n) < 0 : la suite est décroissante"},{"id":"b","texte":"u(n+1) − u(n) > 0 : la suite est croissante"},{"id":"c","texte":"On ne peut rien dire sans calculer tous les termes"},{"id":"d","texte":"Le signe change : la suite n’est pas monotone"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":28,"tolerance":0},"affichage":"28","explication":"u(3) = 3 × u(2) − 2 = 3 × 10 − 2 = **28**."},{"cle":{"type":"nombre","valeur":82,"tolerance":0},"affichage":"82","explication":"u(4) = 3 × 28 − 2 = 84 − 2 = **82**."},{"cle":{"type":"nombre","valeur":244,"tolerance":0},"affichage":"244","explication":"u(5) = 3 × 82 − 2 = 246 − 2 = **244**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Vérifier quelques termes **ne démontre rien** pour tous les rangs. La formule est plausible (c’est bien la bonne), mais il faut la prouver."},{"cle":{"type":"choix","ids":["b"]},"explication":"Si u(n) ≥ 2, alors 2u(n) − 2 ≥ 2 > 0 : la différence est **positive** pour tout n, donc la suite est **croissante**."}]$ex$::jsonb),
  ('eeebd464-f6a5-54f6-a01f-7f7e881bc51e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le tarif de la salle d’escalade","competence":"modeliser","situation":"Maya s’inscrit dans une salle d’escalade. Elle note u(n) la somme totale qu’elle a payée après n mois d’abonnement, inscription comprise : u(0) = 20 €.","documents":[{"id":"tarif","type":"fiche","modele":"affiche","entete":"Escalade du Vieux Port","sousTitre":"Tarifs de l’année","emoji":"🧗","lignes":[{"texte":"Inscription (une seule fois)","valeur":"20 €","id":"z1"},{"separateur":true},{"texte":"Abonnement, chaque mois","valeur":"15 €","id":"z2"}],"pied":"Salle imaginée pour l’exercice","teinte":"bleu"}],"questions":[{"enonce":"Touche la ligne qui donne la raison de la suite (ce qu’on ajoute chaque mois).","aide":"La raison est ce qui s’ajoute à chaque nouveau terme.","type":"zone","document":"tarif","multiple":false},{"enonce":"Combien Maya a-t-elle payé en tout après 4 mois ?","aide":"Utilise u(n) = u(0) + n × r.","type":"nombre","unite":"€"},{"enonce":"Après combien de mois Maya a-t-elle payé 125 € en tout ?","aide":"Retire d’abord l’inscription, puis cherche combien de mensualités de 15 € il faut.","type":"nombre","unite":"mois"},{"enonce":"De quel type est la suite (u) ?","aide":"On passe d’un terme au suivant en ajoutant ou en multipliant ?","type":"choix","options":[{"id":"a","texte":"Arithmétique de raison 20"},{"id":"b","texte":"Arithmétique de raison 15"},{"id":"c","texte":"Géométrique de raison 1,15"},{"id":"d","texte":"Géométrique de raison 15"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"On ajoute **15 €** chaque mois : la raison est r = 15. L’inscription, elle, n’est payée qu’une fois : c’est u(0)."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80 €","explication":"u(4) = 20 + 4 × 15 = 20 + 60 = **80 €**."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 mois","explication":"125 − 20 = 105 et 105 ÷ 15 = **7** mois."},{"cle":{"type":"choix","ids":["b"]},"explication":"On **ajoute** toujours 15 € : la suite est **arithmétique de raison 15**."}]$ex$::jsonb),
  ('eeebd464-f6a5-54f6-a01f-7f7e881bc51e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le scooter qui perd de la valeur","competence":"calculer","situation":"Hugo a acheté un scooter 3 000 €. Chaque année, sa valeur de revente baisse, et il a noté les valeurs des premières années dans un tableau.","documents":[{"id":"valeurs","type":"tableau","titre":"Valeur du scooter","colonnes":["Année n","0","1","2","3","4"],"lignes":[["Valeur (€)",3000,2700,2430,2187,"?"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Quelle est la nature de la suite des valeurs ?","aide":"Calcule 2700 − 3000 puis 2430 − 2700 : sont-ils égaux ? Essaie aussi les quotients.","type":"choix","options":[{"id":"a","texte":"Géométrique : le quotient est constant"},{"id":"b","texte":"Ni l’une ni l’autre"},{"id":"c","texte":"Arithmétique : la différence est constante"},{"id":"d","texte":"Arithmétique : le quotient est constant"}],"multiple":false},{"enonce":"Quelle est la raison q de cette suite ?","aide":"Divise un terme par le précédent.","type":"nombre"},{"enonce":"Calcule la valeur du scooter la 4e année (case manquante).","aide":"Multiplie la valeur de la 3e année par la raison.","type":"nombre","unite":"€"},{"enonce":"Hugo pense que deux baisses de 10 % font 20 %. Quel est le **vrai** pourcentage de baisse entre l’année 0 et l’année 2 ?","aide":"Compare 2430 à 3000 : quelle part de la valeur initiale a disparu ?","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"Les différences valent −300 puis −270 : elles varient. Les quotients valent 0,9 à chaque fois : la suite est **géométrique**."},{"cle":{"type":"nombre","valeur":0.9,"tolerance":0},"affichage":"0,9","explication":"q = 2700 ÷ 3000 = **0,9**, ce qui correspond à une baisse de 10 % par an."},{"cle":{"type":"nombre","valeur":1968.3,"tolerance":0.05},"affichage":"1968,3 €","explication":"u(4) = 2187 × 0,9 = **1 968,3 €**."},{"cle":{"type":"nombre","valeur":19,"tolerance":0},"affichage":"19 %","explication":"La valeur passe de 3 000 à 2 430 : elle a perdu 570 €, soit 570 ÷ 3 000 = 0,19. C’est une baisse de **19 %** (0,9 × 0,9 = 0,81)."}]$ex$::jsonb),
  ('eeebd464-f6a5-54f6-a01f-7f7e881bc51e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La vidéo qui fait le tour du lycée","competence":"modeliser","situation":"Inès publie une vidéo le jour 0. Un article de blog imaginaire raconte comment elle s’est répandue, et un tableau résume l’audience. Tu vas prévoir la suite.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Buzz au lycée","blocs":["Le jour 0, une seule personne regarde la vidéo d’Inès.","Chaque jour qui suit, chaque nouveau spectateur la partage à trois personnes qui ne l’avaient pas encore vue, et ces trois personnes la regardent."],"source":"Article imaginé pour l’exercice"},{"id":"audience","type":"tableau","titre":"L’audience jour après jour","colonnes":["Jour","0","1","2","3","4"],"lignes":[["Nouveaux spectateurs",1,3,9,27,81],["Total depuis le début",1,4,13,40,"?"]],"enteteLignes":true}],"questions":[{"enonce":"Les nouveaux spectateurs forment une suite géométrique. Quelle est sa raison ?","aide":"Divise le nombre de nouveaux spectateurs d’un jour par celui de la veille.","type":"nombre"},{"enonce":"Calcule le total des spectateurs depuis le début, au jour 4.","aide":"Additionne 1 + 3 + 9 + 27 + 81, ou ajoute 81 au total du jour 3.","type":"nombre"},{"enonce":"Combien de nouveaux spectateurs le jour 6 ?","aide":"Le jour n, il y a 3ⁿ nouveaux spectateurs.","type":"nombre"},{"enonce":"Calcule le total depuis le début au jour 6, avec la formule 1 + q + q² + … + qⁿ = (1 − qⁿ⁺¹) ÷ (1 − q).","aide":"Ici q = 3 et n = 6 : calcule 3⁷ = 2 187.","type":"nombre"},{"enonce":"Quel est le premier jour où il y a plus de 10 000 nouveaux spectateurs en une seule journée ?","aide":"Calcule 3⁷, 3⁸, 3⁹ jusqu’à dépasser 10 000.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"9 ÷ 3 = 27 ÷ 9 = **3** : chaque jour, il y a trois fois plus de nouveaux spectateurs."},{"cle":{"type":"nombre","valeur":121,"tolerance":0},"affichage":"121","explication":"40 + 81 = **121** spectateurs au total."},{"cle":{"type":"nombre","valeur":729,"tolerance":0},"affichage":"729","explication":"u(6) = 1 × 3⁶ = **729**."},{"cle":{"type":"nombre","valeur":1093,"tolerance":0},"affichage":"1093","explication":"(1 − 3⁷) ÷ (1 − 3) = (1 − 2 187) ÷ (−2) = −2 186 ÷ (−2) = **1 093**."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"3⁸ = 6 561 (pas assez) et 3⁹ = 19 683 : c’est le jour **9**."}]$ex$::jsonb),
  ('f1f102fd-877d-5c7c-8d82-0b9e961183bf'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une parabole à lire","competence":"lire-graphique","situation":"On a tracé la courbe d’une fonction f du second degré, f(x) = x² − 4x + 3, à partir de quelques points entre x = −1 et x = 5.","documents":[{"id":"parabole","type":"graphique","forme":"courbe","titre":"La courbe de f","categories":["−1","0","1","2","3","4","5"],"series":[{"nom":"f(x)","valeurs":[8,3,0,-1,0,3,8],"teinte":"violet"}],"axeY":{"titre":"f(x)","min":-2,"max":8,"pas":2},"axeX":{"titre":"x"},"valeurs":false,"source":"Valeurs calculées pour l’exercice"}],"questions":[{"enonce":"Touche le sommet de la parabole.","aide":"Le sommet est le point où la courbe change de sens.","type":"zone","document":"parabole","multiple":false},{"enonce":"Touche les deux points où la courbe coupe l’axe des abscisses (les racines).","aide":"Ces points ont une ordonnée égale à 0.","type":"zone","document":"parabole","multiple":true},{"enonce":"Quelle est l’équation x = … de l’axe de symétrie ? Donne la valeur.","aide":"L’axe passe par le sommet ; il est à égale distance des deux racines.","type":"nombre"},{"enonce":"Que dit la forme de la parabole sur le signe de a ?","aide":"Le sommet est-il un minimum ou un maximum ?","type":"choix","options":[{"id":"a","texte":"a est positif : parabole tournée vers le bas"},{"id":"b","texte":"a est positif : parabole tournée vers le haut"},{"id":"c","texte":"a est négatif : parabole tournée vers le haut"},{"id":"d","texte":"a est négatif : parabole tournée vers le bas"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Le sommet est en **x = 2**, au point de coordonnées (2 ; −1) : c’est le minimum de la fonction."},{"cle":{"type":"zone","ids":["k2","k4"]},"explication":"Les racines sont **x = 1** et **x = 3** : on a f(1) = 0 et f(3) = 0."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"La parabole est symétrique par rapport à la droite verticale **x = 2**, milieu de 1 et 3, et abscisse du sommet."},{"cle":{"type":"choix","ids":["b"]},"explication":"La courbe a un **minimum** : elle est tournée vers le haut, donc **a > 0** (ici a = 1)."}]$ex$::jsonb),
  ('f1f102fd-877d-5c7c-8d82-0b9e961183bf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le lancer du ballon","competence":"modeliser","situation":"Au gymnase, Lila lance un ballon droit vers le haut. La hauteur du ballon au bout de t secondes est h(t) = −5t² + 20t, en mètres. Elle a relevé quelques valeurs.","documents":[{"id":"lancer","type":"tableau","titre":"Hauteur du ballon","colonnes":["Temps t (s)","0","1","2","3","4"],"lignes":[["Hauteur h (m)",0,15,20,"?",0]],"enteteLignes":true,"source":"Modèle simplifié, valeurs calculées pour l’exercice"}],"questions":[{"enonce":"Calcule la hauteur manquante h(3).","aide":"Remplace t par 3 : −5 × 9 + 20 × 3.","type":"nombre","unite":"m"},{"enonce":"À quel instant (en secondes) le ballon est-il le plus haut ? Utilise t = −b ÷ (2a).","aide":"Ici a = −5 et b = 20.","type":"nombre","unite":"s"},{"enonce":"Quelle est la hauteur maximale du ballon ?","aide":"Calcule h à l’instant du sommet.","type":"nombre","unite":"m"},{"enonce":"Pendant combien de secondes le ballon est-il à plus de 15 m ? Résous −5t² + 20t − 15 > 0, c’est-à-dire t² − 4t + 3 < 0.","aide":"Cherche les racines de t² − 4t + 3 : le trinôme est négatif entre elles.","type":"nombre","unite":"s"}]}$ex$::jsonb,
