  ('f1f102fd-877d-5c7c-8d82-0b9e961183bf'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’enclos de Mathilde","competence":"modeliser","situation":"Mathilde dispose de 40 m de grillage pour clôturer un enclos rectangulaire contre un mur : le mur sert de quatrième côté. Elle pose x mètres pour la longueur des deux côtés perpendiculaires au mur.","documents":[{"id":"plan","type":"figure","titre":"Plan de l’enclos","cadre":{"xmin":0,"xmax":12,"ymin":0,"ymax":8},"points":[{"id":"A","x":2,"y":1,"position":"so"},{"id":"B","x":10,"y":1,"position":"se"},{"id":"C","x":10,"y":6,"position":"ne"},{"id":"D","x":2,"y":6,"position":"no"}],"segments":[{"de":"A","a":"D","longueur":"x"},{"de":"B","a":"C","longueur":"x"},{"de":"D","a":"C","longueur":"40 − 2x"},{"de":"A","a":"B","style":"pointilles"}],"polygones":[{"sommets":["A","B","C","D"],"teinte":"vert","motif":"clair"}],"textes":[{"x":6,"y":0.4,"texte":"Mur"}],"source":"Plan schématique, hors échelle"},{"id":"aires","type":"tableau","titre":"Quelques aires calculées","colonnes":["x (m)","2","5","15","18"],"lignes":[["Aire A(x) (m²)",72,150,150,72]],"enteteLignes":true,"source":"Valeurs calculées pour l’exercice"}],"questions":[{"enonce":"Quelle est l’expression de l’aire A(x) de l’enclos ?","aide":"Aire d’un rectangle : largeur × longueur, avec les dimensions du plan.","type":"choix","options":[{"id":"a","texte":"A(x) = x(40 − 2x) = −2x² + 40x"},{"id":"b","texte":"A(x) = x² + (40 − 2x)"},{"id":"c","texte":"A(x) = 2x(40 − 2x) = −4x² + 80x"},{"id":"d","texte":"A(x) = x(40 − x) = −x² + 40x"}],"multiple":false},{"enonce":"Le tableau donne la même aire pour x = 5 et x = 15. Quelle est l’abscisse du sommet de la parabole ?","aide":"Le sommet est au milieu de deux abscisses qui donnent la même valeur.","type":"nombre"},{"enonce":"Quelle est l’aire maximale de l’enclos ?","aide":"Calcule A à l’abscisse du sommet.","type":"nombre","unite":"m²"},{"enonce":"On veut une aire de 192 m². Calcule le discriminant Δ de −2x² + 40x − 192 = 0.","aide":"Δ = b² − 4ac avec a = −2, b = 40 et c = −192.","type":"nombre"},{"enonce":"Quelle est la plus petite valeur de x qui donne une aire de 192 m² ?","aide":"Racines : (−b ± √Δ) ÷ (2a), avec √64 = 8.","type":"nombre","unite":"m"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"Largeur x et longueur 40 − 2x : A(x) = x(40 − 2x) = **−2x² + 40x**."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10","explication":"L’axe de symétrie passe par le milieu de 5 et 15 : **x = 10** (on le retrouve par −b ÷ (2a) = −40 ÷ (−4))."},{"cle":{"type":"nombre","valeur":200,"tolerance":0},"affichage":"200 m²","explication":"A(10) = 10 × (40 − 20) = 10 × 20 = **200 m²**."},{"cle":{"type":"nombre","valeur":64,"tolerance":0},"affichage":"64","explication":"Δ = 40² − 4 × (−2) × (−192) = 1 600 − 1 536 = **64**."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 m","explication":"x = (−40 − 8) ÷ (−4) = 12 et x = (−40 + 8) ÷ (−4) = 8. La plus petite est **8 m** (A(8) = 8 × 24 = 192)."}]$ex$::jsonb),
  ('b7e9b515-1990-52f7-8eed-93a4c14d2ff0'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La tangente en un point","competence":"lire-graphique","situation":"On étudie la fonction f définie par f(x) = x². On s’intéresse à la tangente à sa courbe au point A d’abscisse 3. Voici quelques points de la courbe.","documents":[{"id":"carre","type":"graphique","forme":"courbe","titre":"La courbe de f(x) = x²","categories":["−1","0","1","2","3","4"],"series":[{"nom":"f(x)","valeurs":[1,0,1,4,9,16],"teinte":"violet"}],"axeY":{"titre":"f(x)","min":0,"max":16,"pas":4},"axeX":{"titre":"x"},"valeurs":false,"source":"Valeurs calculées pour l’exercice"}],"questions":[{"enonce":"Touche le point A de la courbe, d’abscisse 3.","aide":"Repère l’abscisse 3 sur l’axe horizontal.","type":"zone","document":"carre","multiple":false},{"enonce":"Lis f(3), l’ordonnée du point A.","aide":"Monte jusqu’au point A et lis sur l’axe vertical.","type":"nombre"},{"enonce":"Calcule le nombre dérivé f′(3), avec f′(x) = 2x.","aide":"Remplace x par 3 dans 2x.","type":"nombre"},{"enonce":"Quelle est l’équation de la tangente en A, d’après y = f′(3)(x − 3) + f(3) ?","aide":"Développe 6(x − 3) + 9.","type":"choix","options":[{"id":"a","texte":"y = 6x − 9"},{"id":"b","texte":"y = 6x − 18"},{"id":"c","texte":"y = 9x − 6"},{"id":"d","texte":"y = 3x + 9"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"Le point A est celui d’abscisse **3**, d’ordonnée f(3) = 9."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"f(3) = 3² = **9**, donc A(3 ; 9)."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"f′(3) = 2 × 3 = **6** : c’est le coefficient directeur de la tangente en A."},{"cle":{"type":"choix","ids":["a"]},"explication":"y = 6(x − 3) + 9 = 6x − 18 + 9 = **6x − 9**."}]$ex$::jsonb),
  ('b7e9b515-1990-52f7-8eed-93a4c14d2ff0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les dérivées du tableau noir","competence":"calculer","situation":"Au tableau, le professeur a écrit quatre fonctions et leurs dérivées, mais il a effacé les dérivées. À toi de les retrouver. Léo, lui, propose ensuite une dérivée pour un produit.","documents":[{"id":"fonctions","type":"tableau","titre":"Fonctions à dériver","colonnes":["Fonction","Sa dérivée"],"lignes":[["f(x) = x⁴","?"],["g(x) = 1/x, pour x ≠ 0","?"],["h(x) = √x, pour x > 0","?"],["k(x) = 5x² − 3x","?"]],"enteteLignes":true,"source":"Fonctions choisies pour l’exercice"},{"id":"leo","type":"texte","genre":"consigne","titre":"La proposition de Léo","blocs":["Pour p(x) = x²(x + 1), Léo écrit : p′(x) = 2x × 1 = 2x."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Associe chaque fonction à sa dérivée.","aide":"Rappelle-toi les dérivées usuelles : xⁿ, 1/x, √x, et dérive terme à terme pour k.","type":"association","gauche":[{"id":"g0","texte":"f(x) = x⁴"},{"id":"g1","texte":"g(x) = 1/x"},{"id":"g2","texte":"h(x) = √x"},{"id":"g3","texte":"k(x) = 5x² − 3x"}],"droite":[{"id":"d0","texte":"10x − 3"},{"id":"d1","texte":"1/(2√x)"},{"id":"d2","texte":"−1/x²"},{"id":"d3","texte":"4x³"}]},{"enonce":"Calcule k′(2).","aide":"k′(x) = 10x − 3 ; remplace x par 2.","type":"nombre"},{"enonce":"Quelle est l’erreur de Léo pour dériver le produit x²(x + 1) ?","aide":"Quelle est la formule de dérivation d’un produit u × v ?","type":"choix","options":[{"id":"a","texte":"Il a dérivé chaque facteur et multiplié les dérivées"},{"id":"b","texte":"Il a oublié de développer le produit"},{"id":"c","texte":"Il a confondu dérivée et primitive"},{"id":"d","texte":"Il a dérivé x² avec la formule d’une somme"}],"multiple":false},{"enonce":"Calcule correctement p′(1), avec p′ = u′v + uv′ où u(x) = x² et v(x) = x + 1.","aide":"u′(x) = 2x et v′(x) = 1 ; calcule chaque terme en x = 1.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"(xⁿ)′ = n·xⁿ⁻¹ donne **4x³** ; (1/x)′ = **−1/x²** ; (√x)′ = **1/(2√x)** ; (5x² − 3x)′ = 5 × 2x − 3 = **10x − 3**."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17","explication":"k′(2) = 10 × 2 − 3 = 20 − 3 = **17**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La dérivée d’un produit n’est **pas** le produit des dérivées : (uv)′ = u′v + uv′."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"p′(1) = 2 × 1 × (1 + 1) + 1² × 1 = 4 + 1 = **5**. (Avec p(x) = x³ + x², on retrouve p′(1) = 3 + 2 = 5.)"}]$ex$::jsonb),
  ('b7e9b515-1990-52f7-8eed-93a4c14d2ff0'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une fonction qui monte, descend, remonte","competence":"raisonner","situation":"On étudie f(x) = 2x³ − 3x² − 12x + 5 sur ℝ. Un tableau de valeurs et la courbe correspondante ont été tracés pour x de −2 à 3. Il s’agit de relier la dérivée au comportement de f.","documents":[{"id":"valeurs","type":"tableau","titre":"Valeurs de f","colonnes":["x","−2","−1","0","1","2","3"],"lignes":[["f(x)",1,12,5,-8,-15,-4]],"enteteLignes":true,"source":"Valeurs calculées pour l’exercice"},{"id":"courbe","type":"graphique","forme":"courbe","titre":"La courbe de f","categories":["−2","−1","0","1","2","3"],"series":[{"nom":"f(x)","valeurs":[1,12,5,-8,-15,-4],"teinte":"violet"}],"axeY":{"titre":"f(x)","min":-16,"max":16,"pas":4},"axeX":{"titre":"x"},"valeurs":false}],"questions":[{"enonce":"Quelle est la dérivée de f ?","aide":"Dérive terme à terme : (2x³)′ = 6x², (3x²)′ = 6x, (12x)′ = 12. Factorise ensuite.","type":"choix","options":[{"id":"a","texte":"f′(x) = 2x² − 3x − 12"},{"id":"b","texte":"f′(x) = 6x² − 3x − 12"},{"id":"c","texte":"f′(x) = 6x² − 6x − 12 = 6(x − 4)(x + 3)"},{"id":"d","texte":"f′(x) = 6x² − 6x − 12 = 6(x − 2)(x + 1)"}],"multiple":false},{"enonce":"Calcule f′(0).","aide":"Remplace x par 0 dans 6x² − 6x − 12.","type":"nombre"},{"enonce":"Touche le maximum local de f sur le graphique.","aide":"Cherche le sommet de la bosse, là où la courbe cesse de monter.","type":"zone","document":"courbe","multiple":false},{"enonce":"Que dire du signe de f′ et du sens de variation de f sur ]−1 ; 2[ ?","aide":"Essaie f′(0) : quel est son signe ? Regarde aussi la courbe entre −1 et 2.","type":"choix","options":[{"id":"a","texte":"f′ est positive et f est décroissante"},{"id":"b","texte":"f′ est négative et f est décroissante"},{"id":"c","texte":"f′ est négative et f est croissante"},{"id":"d","texte":"f′ est positive et f est croissante"}],"multiple":false},{"enonce":"Donne l’ordonnée à l’origine de la tangente à la courbe en x = 1, d’équation y = f′(1)(x − 1) + f(1).","aide":"Calcule f′(1) puis développe : y = f′(1)x − f′(1) + f(1).","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"f′(x) = 6x² − 6x − 12. En factorisant : 6(x² − x − 2) = **6(x − 2)(x + 1)**, de racines 2 et −1."},{"cle":{"type":"nombre","valeur":-12,"tolerance":0},"affichage":"−12","explication":"f′(0) = **−12** : la courbe descend en x = 0, avec une pente de −12."},{"cle":{"type":"zone","ids":["k1"]},"explication":"Le maximum local est en **x = −1** : f′ s’annule et passe de positive à négative, avec f(−1) = 12."},{"cle":{"type":"choix","ids":["b"]},"explication":"Sur ]−1 ; 2[, f′(x) = 6(x − 2)(x + 1) < 0 (par exemple f′(0) = −12) : **f est décroissante**, comme le montre la courbe."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"f(1) = −8 et f′(1) = 6 − 6 − 12 = −12. Alors y = −12(x − 1) − 8 = −12x + 12 − 8 = **−12x + 4** : l’ordonnée à l’origine est 4."}]$ex$::jsonb),
  ('0f37b297-bf85-5425-869c-9a597dcbc303'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La courbe qui monte et qui redescend","competence":"lire-graphique","situation":"La courbe d’une fonction f est tracée pour x entre 0 et 6. Tu vas y lire des valeurs et repérer ses extremums.","documents":[{"id":"f","type":"graphique","forme":"courbe","titre":"La courbe de f sur [0 ; 6]","categories":["0","1","2","3","4","5","6"],"series":[{"nom":"f(x)","valeurs":[2,5,7,6,3,1,4],"teinte":"violet"}],"axeY":{"titre":"f(x)","min":0,"max":8,"pas":1},"axeX":{"titre":"x"},"valeurs":false,"source":"Courbe imaginée pour l’exercice"}],"questions":[{"enonce":"Lis la valeur de f(4).","aide":"Place-toi à l’abscisse 4 puis lis l’ordonnée du point de la courbe.","type":"nombre"},{"enonce":"Touche le point où f atteint son maximum.","aide":"Cherche le point le plus haut de la courbe.","type":"zone","document":"f","multiple":false},{"enonce":"Touche le point où f atteint son minimum.","aide":"Cherche le point le plus bas de la courbe.","type":"zone","document":"f","multiple":false},{"enonce":"Sur quels intervalles la fonction f est-elle croissante ?","aide":"Parcours la courbe de gauche à droite et note quand elle monte.","type":"choix","options":[{"id":"a","texte":"[0 ; 2] et [5 ; 6]"},{"id":"b","texte":"[0 ; 5] seulement"},{"id":"c","texte":"[0 ; 6] en entier"},{"id":"d","texte":"[2 ; 5] seulement"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0.1},"affichage":"3","explication":"Au point d’abscisse 4, l’ordonnée vaut **3** : f(4) = 3."},{"cle":{"type":"zone","ids":["k2"]},"explication":"Le maximum de f est atteint en **x = 2**, avec f(2) = 7."},{"cle":{"type":"zone","ids":["k5"]},"explication":"Le minimum de f est atteint en **x = 5**, avec f(5) = 1."},{"cle":{"type":"choix","ids":["a"]},"explication":"La courbe **monte** de x = 0 à 2, **descend** de 2 à 5, puis **remonte** de 5 à 6 : f est croissante sur [0 ; 2] et sur [5 ; 6]."}]$ex$::jsonb),
  ('0f37b297-bf85-5425-869c-9a597dcbc303'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Une boîte pas comme les autres","competence":"raisonner","situation":"Noé étudie la fonction f définie sur ]0 ; +∞[ par f(x) = x + 4/x. Il a calculé sa dérivée, f′(x) = 1 − 4/x², et quelques valeurs de f dans un tableau.","documents":[{"id":"valeurs","type":"tableau","titre":"Valeurs de f","colonnes":["x","1","2","4","8"],"lignes":[["f(x)",5,4,5,8.5]],"enteteLignes":true,"source":"Valeurs calculées pour l’exercice"}],"questions":[{"enonce":"Quelle est la valeur interdite de l’ensemble de définition de x + 4/x ?","aide":"Il y a une division : par quel nombre ne peut-on pas diviser ?","type":"nombre"},{"enonce":"Pour quelle valeur positive de x la dérivée f′(x) = 1 − 4/x² s’annule-t-elle ?","aide":"Résous 1 = 4/x², c’est-à-dire x² = 4, avec x > 0.","type":"nombre"},{"enonce":"f est décroissante sur ]0 ; 2] puis croissante sur [2 ; +∞[. Quel est le minimum de f ?","aide":"Le minimum est la valeur de f là où elle change de sens.","type":"nombre"},{"enonce":"Combien de solutions l’équation f(x) = 3 admet-elle ?","aide":"Compare 3 au minimum de f.","type":"nombre"},{"enonce":"Combien de solutions l’équation f(x) = 5 admet-elle ?","aide":"Regarde le tableau : f vaut déjà 5 pour deux valeurs de x. Utilise les variations.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0,"tolerance":0},"affichage":"0","explication":"On ne divise jamais par 0 : la valeur interdite est **0** (d’où ]0 ; +∞[)."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"1 − 4/x² = 0 ⇔ x² = 4 ⇔ x = 2 (car x > 0). La dérivée s’annule en **2**."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Le minimum est atteint en x = 2 et vaut f(2) = 2 + 4/2 = **4**."},{"cle":{"type":"nombre","valeur":0,"tolerance":0},"affichage":"0","explication":"f(x) ≥ 4 pour tout x > 0 : l’équation f(x) = 3 n’a **aucune** solution."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"f décroît de +∞ à 4 sur ]0 ; 2] puis croît de 4 à +∞ : 5 est atteint **deux fois**, en x = 1 et en x = 4."}]$ex$::jsonb),
  ('0f37b297-bf85-5425-869c-9a597dcbc303'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Encadrer une solution","competence":"raisonner","situation":"On veut montrer que l’équation x³ + x − 1 = 0 admet une unique solution α dans [0 ; 1], puis l’encadrer. On pose f(x) = x³ + x − 1.","documents":[{"id":"consigne","type":"texte","genre":"consigne","titre":"La question","blocs":["f(x) = x³ + x − 1, sur l’intervalle [0 ; 1].","On veut prouver que f(x) = 0 a une seule solution α et en donner un encadrement précis."],"source":"Texte écrit pour l’exercice"},{"id":"balayage","type":"tableau","titre":"Un début de balayage à la calculatrice","colonnes":["x","0","0,6","0,65","0,7","1"],"lignes":[["f(x)",-1,-0.184,-0.075,0.043,1]],"enteteLignes":true,"source":"Valeurs arrondies au millième"}],"questions":[{"enonce":"Que peut-on affirmer à propos de f, de f′(x) = 3x² + 1 et du nombre de solutions de f(x) = 0 dans [0 ; 1] ?","aide":"Quel est le signe de 3x² + 1 ? Et où se trouve 0 par rapport à f(0) et f(1) ?","type":"choix","options":[{"id":"a","texte":"f est strictement décroissante : une unique solution"},{"id":"b","texte":"f′ s’annule en 0 : deux solutions possibles"},{"id":"c","texte":"f est continue, sans plus : au moins une solution seulement"},{"id":"d","texte":"f est strictement croissante : une unique solution"}],"multiple":false},{"enonce":"Dans le tableau, touche les deux valeurs de f entre lesquelles le signe change.","aide":"Cherche où l’on passe d’une valeur négative à une valeur positive.","type":"zone","document":"balayage","multiple":true},{"enonce":"Calcule f(0,68), arrondi au millième.","aide":"Calcule 0,68³ = 0,314432, puis ajoute 0,68 et retire 1.","type":"nombre"},{"enonce":"Sachant f(0,68) ≈ −0,006 et f(0,69) ≈ 0,019, quel est l’encadrement de α au centième ?","aide":"f est strictement croissante : cherche où f change de signe.","type":"choix","options":[{"id":"a","texte":"0,6 < α < 0,65"},{"id":"b","texte":"0,69 < α < 0,7"},{"id":"c","texte":"0,65 < α < 0,68"},{"id":"d","texte":"0,68 < α < 0,69"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"3x² + 1 > 0 : f est **strictement croissante**. Comme f(0) = −1 < 0 < 1 = f(1), le théorème des valeurs intermédiaires donne **une unique** solution α."},{"cle":{"type":"zone","ids":["r0c3","r0c4"]},"explication":"Le signe change entre f(0,65) = −0,075 et f(0,7) = 0,043 : donc α se trouve entre **0,65 et 0,7**."},{"cle":{"type":"nombre","valeur":-0.006,"tolerance":0.0006},"affichage":"−0,006","explication":"f(0,68) = 0,314432 + 0,68 − 1 = −0,005568, soit environ **−0,006**."},{"cle":{"type":"choix","ids":["d"]},"explication":"f(0,68) < 0 < f(0,69) et f est strictement croissante : **0,68 < α < 0,69**."}]$ex$::jsonb),
