   $ex${"titre":"La courbe de l’exponentielle","competence":"lire-graphique","situation":"On a tracé la fonction exponentielle pour x de −2 à 2, à partir de valeurs arrondies au centième. Observe bien sa forme.","documents":[{"id":"exp","type":"graphique","forme":"courbe","titre":"La courbe de la fonction exponentielle","categories":["−2","−1","0","1","2"],"series":[{"nom":"eˣ","valeurs":[0.14,0.37,1,2.72,7.39],"teinte":"violet"}],"axeY":{"titre":"eˣ","min":0,"max":8,"pas":1},"axeX":{"titre":"x"},"valeurs":false,"source":"Valeurs arrondies au centième"}],"questions":[{"enonce":"Touche le point d’abscisse 0 : celui qui illustre e⁰ = 1.","aide":"Repère l’abscisse 0 puis vérifie que l’ordonnée vaut 1.","type":"zone","document":"exp","multiple":false},{"enonce":"Lis une valeur approchée de e¹ = e, au dixième.","aide":"Place-toi à l’abscisse 1 et lis l’ordonnée.","type":"nombre"},{"enonce":"Que peut-on dire de l’équation eˣ = −3 ?","aide":"La courbe est-elle jamais en dessous de l’axe des abscisses ?","type":"choix","options":[{"id":"a","texte":"Une unique solution, qui est positive"},{"id":"b","texte":"Exactement deux solutions opposées"},{"id":"c","texte":"Aucune solution, car eˣ > 0"},{"id":"d","texte":"Une unique solution, qui est négative"}],"multiple":false},{"enonce":"La courbe de la fonction exponentielle, regardée de gauche à droite, est…","aide":"Compare les ordonnées quand x augmente.","type":"choix","options":[{"id":"a","texte":"Constante"},{"id":"b","texte":"Toujours décroissante"},{"id":"c","texte":"Toujours croissante"},{"id":"d","texte":"D’abord décroissante, puis croissante"}],"multiple":false}]}$ex$::jsonb,
