  ('e6b74138-8a5a-5b0b-8d07-3e2b40009735'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les erreurs de Sam","competence":"analyser-document","situation":"Sam a dérivé quatre fonctions de la forme e^u pour s’entraîner. Deux de ses réponses sont fausses. À toi de retrouver lesquelles et de calculer les bonnes valeurs.","documents":[{"id":"sam","type":"tableau","titre":"Les réponses de Sam","colonnes":["Fonction","Dérivée trouvée par Sam"],"lignes":[["e^(3x)","e^(3x)"],["e^(−x)","−e^(−x)"],["e^(x²)","e^(x²)"],["e^(2x+1)","2e^(2x+1)"]],"enteteLignes":true,"source":"Exercice imaginé"}],"questions":[{"enonce":"Touche les deux dérivées fausses.","aide":"Pour (e^u)′, la formule est u′ × e^u. Compare à chaque ligne.","type":"zone","document":"sam","multiple":true},{"enonce":"Quelle est l’erreur commune aux deux réponses fausses ?","aide":"Compare ce que Sam a écrit avec u′ × e^u.","type":"choix","options":[{"id":"a","texte":"Sam a confondu e^u et u^e"},{"id":"b","texte":"Sam a changé le signe de l’exposant"},{"id":"c","texte":"Sam a dérivé u au lieu de e^u"},{"id":"d","texte":"Sam a oublié le facteur u′"}],"multiple":false},{"enonce":"Calcule la dérivée de e^(3x) en x = 0.","aide":"La dérivée est 3e^(3x) ; que vaut e⁰ ?","type":"nombre"},{"enonce":"Calcule la dérivée de e^(x²) en x = 1, arrondie au centième.","aide":"La dérivée est 2x e^(x²) ; en x = 1, calcule 2 × e¹ avec e ≈ 2,718.","type":"nombre"}]}$ex$::jsonb,
