  ('e6b74138-8a5a-5b0b-8d07-3e2b40009735'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le minimum caché dans (x − 1)eˣ","competence":"raisonner","situation":"On étudie la fonction f définie sur ℝ par f(x) = (x − 1)eˣ. On a calculé quelques valeurs et tracé la courbe correspondante. Le but : relier le signe de f′ aux variations.","documents":[{"id":"valeurs","type":"tableau","titre":"Quelques valeurs de f","colonnes":["x","−2","−1","0","1","2"],"lignes":[["f(x)",-0.41,-0.74,-1,0,7.39]],"enteteLignes":true,"source":"Valeurs arrondies au centième"},{"id":"courbe","type":"graphique","forme":"courbe","titre":"La courbe de f","categories":["−2","−1","0","1","2"],"series":[{"nom":"f(x)","valeurs":[-0.41,-0.74,-1,0,7.39],"teinte":"violet"}],"axeY":{"titre":"f(x)","min":-2,"max":8,"pas":2},"axeX":{"titre":"x"},"valeurs":false}],"questions":[{"enonce":"Que vaut f′(x), avec la formule du produit (uv)′ = u′v + uv′ ?","aide":"Prends u(x) = x − 1 et v(x) = eˣ : u′ = 1 et v′ = eˣ.","type":"choix","options":[{"id":"a","texte":"f′(x) = x eˣ"},{"id":"b","texte":"f′(x) = (x − 2)eˣ"},{"id":"c","texte":"f′(x) = (x − 1)eˣ"},{"id":"d","texte":"f′(x) = eˣ"}],"multiple":false},{"enonce":"De quoi dépend le signe de f′(x) = x eˣ ?","aide":"L’exponentielle peut-elle être négative ou nulle ?","type":"choix","options":[{"id":"a","texte":"Du signe de eˣ seulement"},{"id":"b","texte":"Il est toujours positif"},{"id":"c","texte":"Uniquement du signe de x, car eˣ > 0"},{"id":"d","texte":"Du signe de x et de eˣ, tous deux variables"}],"multiple":false},{"enonce":"Quel est le minimum de f ?","aide":"f′ change de signe en x = 0 : calcule f(0).","type":"nombre"},{"enonce":"Résous f(x) = 0 : donne la solution.","aide":"Un produit est nul si l’un de ses facteurs l’est ; eˣ peut-il être nul ?","type":"nombre"},{"enonce":"Calcule f′(−1), arrondie au centième.","aide":"f′(−1) = −1 × e⁻¹ = −1/e ; e ≈ 2,718.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"f′(x) = 1 × eˣ + (x − 1)eˣ = eˣ(1 + x − 1) = **x eˣ**."},{"cle":{"type":"choix","ids":["c"]},"explication":"eˣ est toujours strictement positif : le signe de x eˣ est celui de **x**. f′ est négative pour x < 0 et positive pour x > 0."},{"cle":{"type":"nombre","valeur":-1,"tolerance":0},"affichage":"−1","explication":"f décroît puis croît, avec un changement de sens en 0. Le minimum est f(0) = (0 − 1)e⁰ = **−1**."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"(x − 1)eˣ = 0 avec eˣ ≠ 0 donne x − 1 = 0, donc x = **1**."},{"cle":{"type":"nombre","valeur":-0.37,"tolerance":0.01},"affichage":"−0,37","explication":"f′(−1) = −e⁻¹ = −1/e ≈ **−0,37** : f décroît bien en x = −1."}]$ex$::jsonb),
