   $ex${"titre":"Milieu, pente et distance","competence":"geometrie","situation":"Dans un repère orthonormé, on a placé trois points sur un quadrillage : A(1 ; 1), B(5 ; 3) et C(2 ; 5). On s’intéresse à la droite (AB).","documents":[{"id":"fig","type":"figure","titre":"Le triangle ABC","cadre":{"xmin":0,"xmax":7,"ymin":0,"ymax":6},"quadrillage":true,"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":5,"y":3,"position":"se"},{"id":"C","x":2,"y":5,"position":"no"}],"segments":[{"id":"z1","de":"A","a":"B"},{"de":"A","a":"C"},{"de":"B","a":"C"}],"source":"Figure à l’échelle du quadrillage"}],"questions":[{"enonce":"Touche le segment [AB].","aide":"C’est celui qui relie A(1 ; 1) à B(5 ; 3).","type":"zone","document":"fig","multiple":false},{"enonce":"Quelle est l’ordonnée du milieu M de [AB] ?","aide":"Moyenne des ordonnées de A et de B.","type":"nombre"},{"enonce":"Quel est le coefficient directeur de la droite (AB) ?","aide":"m = (y(B) − y(A)) ÷ (x(B) − x(A)).","type":"nombre"},{"enonce":"Calcule la distance AB, arrondie au centième.","aide":"AB = √((x(B) − x(A))² + (y(B) − y(A))²).","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le segment [AB] relie **A(1 ; 1) et B(5 ; 3)**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"y(M) = (1 + 3) ÷ 2 = **2** (et x(M) = (1 + 5) ÷ 2 = 3)."},{"cle":{"type":"nombre","valeur":0.5,"tolerance":0},"affichage":"0,5","explication":"m = (3 − 1) ÷ (5 − 1) = 2 ÷ 4 = **0,5**."},{"cle":{"type":"nombre","valeur":4.47,"tolerance":0.01},"affichage":"4,47","explication":"AB = √(4² + 2²) = √20 ≈ **4,47**."}]$ex$::jsonb),
  ('7c396887-8da2-5d89-8ea1-1f50c893ed29'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le cercle du jardin","competence":"raisonner","situation":"Dans un repère orthonormé, un bassin circulaire a pour équation x² + y² − 4x + 2y − 4 = 0. Quatre points marquent l’emplacement de quatre statues. Il faut ramener l’équation à une forme lisible.","documents":[{"id":"eq","type":"texte","genre":"consigne","titre":"L’équation du bassin","blocs":["x² + y² − 4x + 2y − 4 = 0","On complète les carrés : x² − 4x = (x − 2)² − 4 et y² + 2y = (y + 1)² − 1."],"source":"Texte écrit pour l’exercice"},{"id":"statues","type":"figure","titre":"Les quatre statues","cadre":{"xmin":-2,"xmax":7,"ymin":-3,"ymax":4},"quadrillage":true,"axes":true,"points":[{"id":"P","x":2,"y":2,"position":"ne"},{"id":"Q","x":4,"y":1,"position":"ne"},{"id":"R","x":5,"y":-1,"position":"se"},{"id":"S","x":0,"y":-1,"position":"o"}],"source":"Positions imaginées pour l’exercice"}],"questions":[{"enonce":"Après avoir complété les carrés, on obtient (x − 2)² + (y + 1)² = k. Quelle est la valeur de k ?","aide":"Ajoute 4 et 1 des deux côtés, puis n’oublie pas le −4 de l’équation.","type":"nombre"},{"enonce":"Quel est le centre Ω du cercle ?","aide":"Dans (x − a)² + (y − b)² = r², le centre est (a ; b) : attention aux signes.","type":"choix","options":[{"id":"a","texte":"Ω(2 ; −1), lu dans (x − 2)² + (y + 1)²"},{"id":"b","texte":"Ω(2 ; 1), signe de y oublié"},{"id":"c","texte":"Ω(4 ; −2), coefficients de x et de y"},{"id":"d","texte":"Ω(−2 ; 1), signes recopiés tels quels"}],"multiple":false},{"enonce":"Quel est le rayon du cercle ?","aide":"r² = 9 ; un rayon est positif.","type":"nombre"},{"enonce":"Touche les deux statues situées exactement sur le bassin.","aide":"Un point (x ; y) est sur le cercle si (x − 2)² + (y + 1)² = 9.","type":"zone","document":"statues","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"x² − 4x + y² + 2y = 4 donne (x − 2)² − 4 + (y + 1)² − 1 = 4, donc (x − 2)² + (y + 1)² = 4 + 4 + 1 = **9**."},{"cle":{"type":"choix","ids":["a"]},"explication":"On lit (x − 2)² + (y − (−1))² = 9 : le centre est **Ω(2 ; −1)**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"r² = 9 donc r = **3**."},{"cle":{"type":"zone","ids":["P","R"]},"explication":"P(2 ; 2) : 0 + 9 = 9 ; R(5 ; −1) : 9 + 0 = 9. Pour Q : 4 + 4 = 8 ; pour S : 4 + 0 = 4. Seules **P et R** sont sur le cercle."}]$ex$::jsonb),
  ('7c396887-8da2-5d89-8ea1-1f50c893ed29'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un triangle rectangle caché","competence":"raisonner","situation":"Dans un repère orthonormé, trois points A, B et C sont donnés par leurs coordonnées. Un élève prétend que le triangle ABC est rectangle. Tu vas vérifier de deux façons, puis décrire son cercle circonscrit.","documents":[{"id":"coordonnees","type":"tableau","titre":"Coordonnées des points","colonnes":["","A","B","C"],"lignes":[["Abscisse",-1,5,1],["Ordonnée",1,3,5]],"enteteLignes":true,"source":"Points choisis pour l’exercice"},{"id":"fig","type":"figure","titre":"Le triangle ABC","cadre":{"xmin":-2,"xmax":6,"ymin":0,"ymax":6},"quadrillage":true,"points":[{"id":"A","x":-1,"y":1,"position":"so"},{"id":"B","x":5,"y":3,"position":"se"},{"id":"C","x":1,"y":5,"position":"no"}],"polygones":[{"sommets":["A","B","C"],"teinte":"violet","motif":"clair"}]}],"questions":[{"enonce":"Calcule le coefficient directeur de la droite (CA).","aide":"m = (y(A) − y(C)) ÷ (x(A) − x(C)).","type":"nombre"},{"enonce":"Calcule le coefficient directeur de la droite (CB).","aide":"m = (y(B) − y(C)) ÷ (x(B) − x(C)).","type":"nombre"},{"enonce":"Le produit des deux coefficients directeurs vaut 2 × (−0,5) = −1. Que peut-on conclure ?","aide":"Rappelle-toi la condition m × m′ = −1.","type":"choix","options":[{"id":"a","texte":"Parallèles : elles ne se coupent pas"},{"id":"b","texte":"Le triangle est rectangle en A, car AB est le plus long côté"},{"id":"c","texte":"Le triangle est isocèle en C, car les pentes sont proches"},{"id":"d","texte":"Perpendiculaires : rectangle en C"}],"multiple":false},{"enonce":"Le cercle circonscrit a pour diamètre l’hypoténuse [AB] et pour centre son milieu I(2 ; 2). Calcule son rayon au carré r².","aide":"r² = IA² ; ou calcule AB² ÷ 4 avec AB² = 6² + 2².","type":"nombre"},{"enonce":"Quelle est l’équation de ce cercle circonscrit ?","aide":"Centre I(2 ; 2) et r² = 10 : (x − a)² + (y − b)² = r².","type":"choix","options":[{"id":"a","texte":"(x − 2)² + (y − 2)² = 10"},{"id":"b","texte":"(x − 5)² + (y − 3)² = 10"},{"id":"c","texte":"(x + 2)² + (y + 2)² = 10 (centre de signe opposé)"},{"id":"d","texte":"(x − 2)² + (y − 2)² = 40"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"m = (1 − 5) ÷ (−1 − 1) = (−4) ÷ (−2) = **2**."},{"cle":{"type":"nombre","valeur":-0.5,"tolerance":0},"affichage":"−0,5","explication":"m = (3 − 5) ÷ (5 − 1) = −2 ÷ 4 = **−0,5**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Deux droites sont perpendiculaires si le produit de leurs coefficients directeurs vaut **−1** : le triangle est **rectangle en C**."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10","explication":"IA² = (−1 − 2)² + (1 − 2)² = 9 + 1 = **10** (et AB² ÷ 4 = 40 ÷ 4 = 10)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le centre est I(2 ; 2) et r² = 10 : **(x − 2)² + (y − 2)² = 10**. On vérifie avec C : (1 − 2)² + (5 − 2)² = 1 + 9 = 10."}]$ex$::jsonb),
