  ('0982f49a-453d-5c24-9144-85bf56d099e7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le test de dépistage qui inquiète à tort","competence":"raisonner","situation":"Un laboratoire présente un test pour une maladie M. Karim vient d’apprendre que son test est positif et s’inquiète. Avant de conclure, il veut calculer la probabilité d’être réellement malade, sachant que le test est positif.","documents":[{"id":"fiche","type":"texte","genre":"consigne","titre":"Les caractéristiques du test","blocs":["1 % de la population est atteint de la maladie M.","Chez un malade, le test est positif dans 95 % des cas.","Chez une personne non malade, le test est positif (à tort) dans 4 % des cas."],"source":"Valeurs imaginées pour l’exercice"},{"id":"dix","type":"tableau","titre":"Pour 10 000 personnes testées","colonnes":["Personnes","Test positif","Test négatif","Total"],"lignes":[["Malades",95,5,100],["Non malades",396,9504,9900],["Total",491,9509,10000]],"enteteLignes":true,"source":"Effectifs arrondis, calculés à partir de la fiche"}],"questions":[{"enonce":"On choisit une personne au hasard. Quelle est la probabilité qu’elle soit malade ET que son test soit positif ?","aide":"P(M ∩ T) = P(M) × P(M)(T), avec les deux pourcentages de la fiche.","type":"nombre"},{"enonce":"Touche la case qui donne le nombre de personnes dont le test est positif alors qu’elles ne sont pas malades.","aide":"Une personne non malade au test positif : ligne « Non malades », colonne « Test positif ».","type":"zone","document":"dix","multiple":false},{"enonce":"Quelle est la probabilité que le test soit positif ?","aide":"Un test positif vient d’un malade ou d’un non-malade : additionne les deux chemins.","type":"nombre"},{"enonce":"Sachant que le test est positif, quelle est la probabilité d’être malade ? Arrondis au millième.","aide":"P(T)(M) = P(M ∩ T) ÷ P(T). Tu as déjà calculé les deux termes.","type":"nombre"},{"enonce":"Que peut-on dire à Karim ?","aide":"0,193 est proche de 0,2. Que vaut 0,2 sous forme de « 1 chance sur … » ?","type":"choix","options":[{"id":"a","texte":"Il a environ 1 chance sur 5 d’être réellement malade"},{"id":"b","texte":"Il a environ 1 chance sur 100 d’être réellement malade"},{"id":"c","texte":"Il est certainement malade, car le test est fiable à 95 %"},{"id":"d","texte":"Il a environ 19 chances sur 20 d’être réellement malade"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.0095,"tolerance":0},"affichage":"0,0095","explication":"P(M ∩ T) = 0,01 × 0,95 = **0,0095**."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Ce sont les faux positifs : **396** personnes sur 10 000."},{"cle":{"type":"nombre","valeur":0.0491,"tolerance":0},"affichage":"0,0491","explication":"P(T) = 0,01 × 0,95 + 0,99 × 0,04 = 0,0095 + 0,0396 = **0,0491**, soit 491 personnes sur 10 000."},{"cle":{"type":"nombre","valeur":0.193,"tolerance":0.0006},"affichage":"0,193","explication":"P(T)(M) = 0,0095 ÷ 0,0491 ≈ **0,193** (on retrouve 95 ÷ 491 avec le tableau)."},{"cle":{"type":"choix","ids":["a"]},"explication":"P(T)(M) ≈ 0,19 : **environ 1 chance sur 5**. Le test est fiable chez les malades (95 %), mais la maladie est rare : la plupart des tests positifs sont de faux positifs."}]$ex$::jsonb),
  ('576b7c68-bf81-5696-b404-8641ef5b2b0a'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La roue des cadeaux à la kermesse","competence":"lire-tableau","situation":"À la kermesse, Yanis tente sa chance à la roue des cadeaux. Le gain X, en euros, dépend de la case où s’arrête la roue. L’organisateur a affiché la loi de X, mais une probabilité est effacée.","documents":[{"id":"loi","type":"tableau","titre":"Loi de probabilité du gain X","colonnes":["Gain X (€)","0","2","5","10"],"lignes":[["Probabilité","0,5","0,3","?","0,05"]],"enteteLignes":true,"source":"Roue imaginée pour l’exercice"}],"questions":[{"enonce":"Quelle est la probabilité effacée, celle de gagner 5 € ?","aide":"La somme des probabilités d’une loi vaut toujours 1.","type":"nombre"},{"enonce":"Quelle est la probabilité de gagner au moins 5 € ?","aide":"Au moins 5 €, c’est 5 € ou 10 € : additionne deux probabilités.","type":"nombre"},{"enonce":"Calcule l’espérance E(X) du gain.","aide":"E(X) = somme des valeurs multipliées par leur probabilité.","type":"nombre","unite":"€"},{"enonce":"Le ticket coûte 2 €. Que peut-on dire de ce jeu ?","aide":"Compare le gain moyen à la mise de 2 €.","type":"choix","options":[{"id":"a","texte":"Il est équitable"},{"id":"b","texte":"Il est favorable à l’organisateur"},{"id":"c","texte":"Il est favorable au joueur"},{"id":"d","texte":"On ne peut pas le savoir avant d’avoir joué"}],"multiple":false}]}$ex$::jsonb,
