  ('576b7c68-bf81-5696-b404-8641ef5b2b0a'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Les buts du FC Rivage","competence":"lire-graphique","situation":"L’entraîneur du FC Rivage a étudié tous les matchs de son équipe sur plusieurs saisons. Il a tracé la loi du nombre X de buts marqués par match, et il veut en déduire la prime versée aux joueurs.","documents":[{"id":"buts","type":"graphique","forme":"barres","titre":"Loi du nombre de buts marqués X","categories":["0","1","2","3","4"],"series":[{"nom":"P(X = k)","valeurs":[20,35,25,15,5],"teinte":"violet"}],"axeY":{"titre":"Probabilité","unite":"en %","min":0,"max":40,"pas":5},"axeX":{"titre":"Nombre de buts k"},"valeurs":false,"source":"Statistiques imaginées pour l’exercice"}],"questions":[{"enonce":"Touche la valeur de X la plus probable.","aide":"Cherche la barre la plus haute.","type":"zone","document":"buts","multiple":false},{"enonce":"Donne P(X ≥ 3) sous forme décimale.","aide":"Additionne les barres de 3 et de 4 buts, puis convertis le pourcentage en décimal.","type":"nombre"},{"enonce":"Calcule l’espérance E(X).","aide":"Multiplie chaque nombre de buts par sa probabilité (en décimal) et additionne.","type":"nombre","unite":"buts"},{"enonce":"Calcule la variance V(X).","aide":"V(X) = somme des x² × P(X = x), moins le carré de E(X).","type":"nombre"},{"enonce":"Le club verse 2 000 € par but marqué plus 1 000 € de prime de match : la prime est P = 2 000 X + 1 000. Quelle est la prime moyenne E(P) ?","aide":"E(aX + b) = a E(X) + b.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1"]},"explication":"La barre la plus haute est celle de **1 but** (35 %)."},{"cle":{"type":"nombre","valeur":0.2,"tolerance":0},"affichage":"0,2","explication":"P(X ≥ 3) = 15 % + 5 % = 20 %, soit **0,2**."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0},"affichage":"1,5 buts","explication":"E(X) = 0 × 0,2 + 1 × 0,35 + 2 × 0,25 + 3 × 0,15 + 4 × 0,05 = 0,35 + 0,5 + 0,45 + 0,2 = **1,5 but** par match."},{"cle":{"type":"nombre","valeur":1.25,"tolerance":0},"affichage":"1,25","explication":"Somme des x² × P : 0,35 + 4 × 0,25 + 9 × 0,15 + 16 × 0,05 = 3,5. Puis V(X) = 3,5 − 1,5² = 3,5 − 2,25 = **1,25**."},{"cle":{"type":"nombre","valeur":4000,"tolerance":0},"affichage":"4000 €","explication":"E(P) = 2 000 × E(X) + 1 000 = 2 000 × 1,5 + 1 000 = **4 000 €**."}]$ex$::jsonb),
  ('576b7c68-bf81-5696-b404-8641ef5b2b0a'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Deux stands, même gain moyen, quel risque ?","competence":"raisonner","situation":"À la fête du lycée, deux stands proposent un jeu gratuit où l’on gagne des euros. Les deux annoncent le même gain moyen. Lina veut savoir lequel est le plus risqué avant d’y emmener sa classe.","documents":[{"id":"standA","type":"tableau","titre":"Stand A : loi du gain","colonnes":["Gain (€)","0","10"],"lignes":[["Probabilité","0,5","0,5"]],"enteteLignes":true,"source":"Lois imaginées pour l’exercice"},{"id":"standB","type":"tableau","titre":"Stand B : loi du gain","colonnes":["Gain (€)","4","5","6"],"lignes":[["Probabilité","0,25","0,5","0,25"]],"enteteLignes":true,"source":"Lois imaginées pour l’exercice"}],"questions":[{"enonce":"Calcule l’espérance du gain au stand A.","aide":"E = 0 × 0,5 + 10 × 0,5.","type":"nombre","unite":"€"},{"enonce":"Calcule l’espérance du gain au stand B.","aide":"Multiplie chaque gain par sa probabilité, puis additionne les trois produits.","type":"nombre","unite":"€"},{"enonce":"Calcule la variance du gain au stand A.","aide":"V = somme des x² × P(X = x) − E². Ici x² vaut 0 ou 100.","type":"nombre"},{"enonce":"Calcule la variance du gain au stand B.","aide":"Même méthode : somme des x² × P, moins le carré de l’espérance.","type":"nombre"},{"enonce":"Quel stand est le plus risqué ?","aide":"Compare les deux variances : la plus grande indique la plus forte dispersion.","type":"choix","options":[{"id":"a","texte":"Le stand B : ses gains s’éloignent davantage de la moyenne"},{"id":"b","texte":"Aucun des deux : même espérance, donc même risque"},{"id":"c","texte":"On ne peut pas comparer : les gains sont différents"},{"id":"d","texte":"Le stand A : ses gains s’éloignent davantage de la moyenne"}],"multiple":false},{"enonce":"Un sponsor double les gains du stand A puis ajoute 3 € : le nouveau gain est Y = 2X + 3. Quelle est la variance de Y ?","aide":"V(aX + b) = a² V(X) : que devient le b ?","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 €","explication":"E(A) = 0 × 0,5 + 10 × 0,5 = **5 €**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 €","explication":"E(B) = 4 × 0,25 + 5 × 0,5 + 6 × 0,25 = 1 + 2,5 + 1,5 = **5 €**. Les deux annonces sont exactes."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25","explication":"Somme des x² × P = 0 × 0,5 + 100 × 0,5 = 50, puis V(A) = 50 − 5² = **25**."},{"cle":{"type":"nombre","valeur":0.5,"tolerance":0},"affichage":"0,5","explication":"Somme des x² × P = 16 × 0,25 + 25 × 0,5 + 36 × 0,25 = 4 + 12,5 + 9 = 25,5, puis V(B) = 25,5 − 25 = **0,5**."},{"cle":{"type":"choix","ids":["d"]},"explication":"V(A) = 25 est bien plus grande que V(B) = 0,5 : **le stand A** est plus risqué. Une même espérance ne dit rien du risque."},{"cle":{"type":"nombre","valeur":100,"tolerance":0},"affichage":"100","explication":"V(Y) = 2² × V(X) = 4 × 25 = **100**. Le + 3 ne change pas la dispersion."}]$ex$::jsonb),
  ('bf08a9a9-57bd-5372-bc84-ba423ad96e4e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La pyramide de boîtes de conserve","competence":"calculer","situation":"Amina empile des boîtes de conserve en pyramide au supermarché : 3 boîtes sur la rangée du haut, puis 2 de plus à chaque rangée en descendant. Elle a noté le début dans un tableau.","documents":[{"id":"rangs","type":"tableau","titre":"Boîtes par rangée","colonnes":["Rangée","1","2","3","4","5"],"lignes":[["Boîtes",3,5,7,9,"?"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Combien de boîtes y a-t-il sur la rangée 5 (case manquante) ?","aide":"On ajoute toujours le même nombre de boîtes d’une rangée à la suivante.","type":"nombre"},{"enonce":"Combien de boîtes sur la rangée 10, tout en bas ?","aide":"u(10) = u(1) + 9 × raison : entre la rangée 1 et la rangée 10, on ajoute 9 fois la raison.","type":"nombre"},{"enonce":"Combien de boîtes la pyramide de 10 rangées compte-t-elle en tout ?","aide":"Somme = nombre de termes × (premier + dernier) ÷ 2.","type":"nombre"},{"enonce":"Combien de boîtes sur les rangées 4 à 10 (rangées 4 et 10 comprises) ?","aide":"Compte d’abord les termes : de la rangée 4 à la rangée 10 inclus, pense au « + 1 ».","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11","explication":"La raison est 2 : 9 + 2 = **11 boîtes**."},{"cle":{"type":"nombre","valeur":21,"tolerance":0},"affichage":"21","explication":"u(10) = 3 + 9 × 2 = **21 boîtes**."},{"cle":{"type":"nombre","valeur":120,"tolerance":0},"affichage":"120","explication":"S = 10 × (3 + 21) ÷ 2 = 10 × 12 = **120 boîtes**."},{"cle":{"type":"nombre","valeur":105,"tolerance":0},"affichage":"105","explication":"De 4 à 10 : 10 − 4 + 1 = 7 rangées. Premier terme u(4) = 9, dernier 21 : S = 7 × (9 + 21) ÷ 2 = 7 × 15 = **105 boîtes**."}]$ex$::jsonb),
  ('bf08a9a9-57bd-5372-bc84-ba423ad96e4e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’invitation qui fait boule de neige","competence":"modeliser","situation":"Un lundi, Léa envoie une invitation à une fête à 3 amis. Chaque jour suivant, chaque personne qui vient de la recevoir la transmet à 3 autres personnes qui ne l’avaient pas encore. Léa suit la diffusion dans un tableau.","documents":[{"id":"diffusion","type":"tableau","titre":"Nouvelles personnes touchées chaque jour","colonnes":["Jour","1","2","3","4","5"],"lignes":[["Nouvelles personnes",3,9,27,81,"?"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Quelle est la raison q de cette suite ?","aide":"Divise un terme par le précédent.","type":"nombre"},{"enonce":"Combien de nouvelles personnes le jour 5 (case manquante) ?","aide":"Multiplie le terme du jour 4 par la raison.","type":"nombre"},{"enonce":"Combien de personnes ont reçu l’invitation en tout au bout de 6 jours (sans compter Léa) ?","aide":"Somme géométrique : premier terme × (1 − q^N) ÷ (1 − q), avec N = 6 termes.","type":"nombre"},{"enonce":"Au bout de quel jour, au plus tôt, plus de 1 000 personnes ont-elles reçu l’invitation ?","aide":"Calcule le total à la fin du jour 5, puis celui du jour 6.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"9 ÷ 3 = 27 ÷ 9 = 81 ÷ 27 = **3** : la suite est géométrique de raison 3."},{"cle":{"type":"nombre","valeur":243,"tolerance":0},"affichage":"243","explication":"81 × 3 = **243**."},{"cle":{"type":"nombre","valeur":1092,"tolerance":0},"affichage":"1092","explication":"S = 3 × (1 − 3⁶) ÷ (1 − 3) = 3 × (1 − 729) ÷ (−2) = 3 × 364 = **1 092 personnes**."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"Après 5 jours : 3 + 9 + 27 + 81 + 243 = 363, c’est moins de 1 000. Après 6 jours : 1 092. C’est donc le **jour 6**."}]$ex$::jsonb),
  ('bf08a9a9-57bd-5372-bc84-ba423ad96e4e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le plan d’entraînement de Sacha","competence":"programmer","situation":"Sacha prépare un 10 km avec le plan de son club. Pour vérifier ses calculs, il a écrit un petit programme Python qui additionne les distances semaine après semaine.","documents":[{"id":"plan","type":"fiche","modele":"affiche","entete":"Club d’athlétisme","sousTitre":"Plan d’entraînement de Sacha","emoji":"🏃","lignes":[{"texte":"Semaine 1","valeur":"5 km","id":"z1"},{"separateur":true},{"texte":"Chaque semaine suivante","valeur":"+ 2 km","id":"z2"},{"texte":"Durée du plan","valeur":"8 semaines","id":"z3"}],"pied":"Plan imaginé pour l’exercice","teinte":"bleu"},{"id":"prog","type":"texte","genre":"consigne","titre":"Le programme de Sacha","blocs":["s = 0","u = 5","for i in range(8):","    s = s + u","    u = u + 2","print(s)"],"source":"Programme écrit pour l’exercice"}],"questions":[{"enonce":"Quelle distance Sacha court-il la semaine 8 ?","aide":"Entre la semaine 1 et la semaine 8, on ajoute 7 fois 2 km.","type":"nombre","unite":"km"},{"enonce":"Dans le programme, que représente la variable u au début de chaque tour de boucle ?","aide":"Regarde ce qu’on ajoute à s à chaque tour, puis ce que devient u à la ligne suivante.","type":"choix","options":[{"id":"a","texte":"La distance totale déjà courue"},{"id":"b","texte":"La distance de la semaine en cours"},{"id":"c","texte":"Le nombre de semaines écoulées"},{"id":"d","texte":"La raison de la suite"}],"multiple":false},{"enonce":"Quelle valeur le programme affiche-t-il à la fin ?","aide":"Il additionne les distances des 8 semaines : utilise la formule de la somme.","type":"nombre","unite":"km"},{"enonce":"On remplace range(8) par range(10). Quelle valeur le programme affiche-t-il alors ?","aide":"Il faut d’abord le dernier terme, pour 10 semaines.","type":"nombre","unite":"km"},{"enonce":"Sacha voudrait avoir couru au moins 200 km au total. Combien de semaines de plan faut-il, au minimum ?","aide":"Pour n semaines, le total vaut n × (10 + 2(n − 1)) ÷ 2, soit n(n + 4). Teste quelques valeurs de n.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":19,"tolerance":0},"affichage":"19 km","explication":"u(8) = 5 + 7 × 2 = **19 km**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Chaque tour ajoute u à s, puis passe à la semaine suivante avec u = u + 2 : u est **la distance de la semaine en cours**, et s le total."},{"cle":{"type":"nombre","valeur":96,"tolerance":0},"affichage":"96 km","explication":"S = 8 × (5 + 19) ÷ 2 = 8 × 12 = **96 km**."},{"cle":{"type":"nombre","valeur":140,"tolerance":0},"affichage":"140 km","explication":"Dernier terme : 5 + 9 × 2 = 23. S = 10 × (5 + 23) ÷ 2 = **140 km**."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13","explication":"Total après n semaines : n(n + 4). Pour n = 12 : 12 × 16 = 192, c’est trop peu. Pour n = 13 : 13 × 17 = 221 ≥ 200. Il faut **13 semaines**."}]$ex$::jsonb),
  ('389e4ddc-4d82-591f-b9d6-657624771756'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Chloé dérive avant le contrôle","competence":"calculer","situation":"La veille d’un contrôle, Chloé a recopié l’aide-mémoire des dérivées de référence. Elle s’entraîne sur une fonction polynôme.","documents":[{"id":"memo","type":"tableau","titre":"Aide-mémoire de Chloé","colonnes":["Fonction f(x)","Dérivée f′(x)"],"lignes":[["x²","2x"],["x³","3x²"],["x","1"],["k (constante)","0"],["1/x","−1/x²"],["√x","1/(2√x)"],["eˣ","eˣ"]],"enteteLignes":true,"source":"Tableau de cours"},{"id":"fonction","type":"texte","genre":"consigne","titre":"La fonction à dériver","blocs":["f(x) = 2x³ − 5x² + 3x − 1, définie sur l’ensemble des réels."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui donne la dérivée de x³.","aide":"Repère la ligne de x³, puis la colonne des dérivées.","type":"zone","document":"memo","multiple":false},{"enonce":"Quelle est la dérivée f′(x) de la fonction de Chloé ?","aide":"Dérive terme à terme : 2x³ → 2 × 3x², puis −5x², puis 3x, puis la constante.","type":"choix","options":[{"id":"a","texte":"f′(x) = 6x² − 10x − 1"},{"id":"b","texte":"f′(x) = 6x² − 5x + 3"},{"id":"c","texte":"f′(x) = 6x² − 10x + 3"},{"id":"d","texte":"f′(x) = 2x² − 10x + 3"}],"multiple":false},{"enonce":"Calcule f′(2).","aide":"Remplace x par 2 dans l’expression de f′(x).","type":"nombre"},{"enonce":"Que peut-on dire du sens de variation de f près de x = 1 ?","aide":"Calcule f′(1) et regarde son signe.","type":"choix","options":[{"id":"a","texte":"On ne peut rien dire sans le tableau de signes complet"},{"id":"b","texte":"f est croissante, car f′(1) = −1 est négatif"},{"id":"c","texte":"f est croissante, car f(1) = −1 est un nombre non nul"},{"id":"d","texte":"f est décroissante, car f′(1) = −1 est négatif"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La ligne de x³ donne **3x²** : on multiplie par l’exposant 3 et on baisse l’exposant de 1."},{"cle":{"type":"choix","ids":["c"]},"explication":"(2x³)′ = 6x², (−5x²)′ = −10x, (3x)′ = 3 et la constante −1 disparaît : **f′(x) = 6x² − 10x + 3**."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7","explication":"f′(2) = 6 × 4 − 10 × 2 + 3 = 24 − 20 + 3 = **7**."},{"cle":{"type":"choix","ids":["d"]},"explication":"f′(1) = 6 − 10 + 3 = −1 < 0 : **f est décroissante** près de 1. C’est le signe de la dérivée qui compte, pas celui de f(1)."}]$ex$::jsonb),
  ('389e4ddc-4d82-591f-b9d6-657624771756'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les dérivées de Malik : où sont les erreurs ?","competence":"raisonner","situation":"Malik a corrigé son devoir sur les dérivées de composées affines. Sa prof a relevé deux erreurs dans son cahier, mais ne dit pas lesquelles.","documents":[{"id":"cahier","type":"tableau","titre":"Le cahier de Malik","colonnes":["Fonction","Dérivée trouvée par Malik"],"lignes":[["(2x + 1)³","3 (2x + 1)²"],["e^(−3x)","−3 e^(−3x)"],["sin(2x)","cos(2x)"],["1/(x + 4)","−1/(x + 4)²"]],"enteteLignes":true,"source":"Résultats écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux dérivées fausses.","aide":"Pour g(ax + b), la dérivée est a × g′(ax + b) : vérifie si le facteur a est bien présent.","type":"zone","document":"cahier","multiple":true},{"enonce":"Quelle erreur Malik commet-il sur la première ligne ?","aide":"Compare avec 3 × 2 × (2x + 1)².","type":"choix","options":[{"id":"a","texte":"Il oublie de multiplier par le coefficient 2 de 2x + 1"},{"id":"b","texte":"Il dérive la parenthèse comme si c’était une somme"},{"id":"c","texte":"Il oublie de dériver : il recopie la fonction telle quelle"},{"id":"d","texte":"Il se trompe sur l’exposant : il fallait garder 3"}],"multiple":false},{"enonce":"Calcule la vraie dérivée de (2x + 1)³ en x = 1.","aide":"Utilise 6 (2x + 1)² et remplace x par 1.","type":"nombre"},{"enonce":"Calcule la vraie dérivée de sin(2x) en x = 0.","aide":"La dérivée est 2 cos(2x) ; que vaut cos(0) ?","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r2c1"]},"explication":"Les deux erreurs sont **(2x + 1)³** (il manque le facteur 2) et **sin(2x)** (il manque aussi le facteur 2). Les deux autres lignes sont justes."},{"cle":{"type":"choix","ids":["a"]},"explication":"Pour g(ax + b), on a a × g′(ax + b). Ici a = 2 : la bonne dérivée est 3 × 2 × (2x + 1)² = **6 (2x + 1)²**."},{"cle":{"type":"nombre","valeur":54,"tolerance":0},"affichage":"54","explication":"6 × (2 × 1 + 1)² = 6 × 9 = **54**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"2 cos(0) = 2 × 1 = **2**."}]$ex$::jsonb),
  ('389e4ddc-4d82-591f-b9d6-657624771756'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une courbe qui monte puis redescend","competence":"modeliser","situation":"Une infirmière étudie la concentration d’un médicament dans le sang, en milligrammes par litre, x heures après la prise. Le modèle est g(x) = x e^(−x), et elle a tracé la courbe ci-dessous.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Concentration g(x) en fonction du temps","categories":["0","0,5","1","1,5","2","2,5","3","3,5","4"],"series":[{"nom":"g(x)","valeurs":[0,0.303,0.368,0.335,0.271,0.205,0.149,0.106,0.073],"teinte":"violet"}],"axeY":{"titre":"Concentration","unite":"mg/L","min":0,"max":0.4,"pas":0.05},"axeX":{"titre":"Temps x (heures)"},"source":"Valeurs calculées, arrondies au millième"},{"id":"modele","type":"texte","genre":"consigne","titre":"Le modèle","blocs":["g(x) = x e^(−x), pour x ≥ 0."],"source":"Modèle écrit pour l’exercice"}],"questions":[{"enonce":"Touche le point de la courbe où la concentration semble la plus élevée.","aide":"Cherche le sommet de la courbe.","type":"zone","document":"courbe","multiple":false},{"enonce":"Quelle est la dérivée de g ?","aide":"Produit uv avec u = x et v = e^(−x), dont la dérivée est −e^(−x) (composée affine, a = −1).","type":"choix","options":[{"id":"a","texte":"g′(x) = (1 − x) e^(−x)"},{"id":"b","texte":"g′(x) = (x + 1) e^x"},{"id":"c","texte":"g′(x) = −x e^(−x)"},{"id":"d","texte":"g′(x) = e^(−x)"}],"multiple":false},{"enonce":"Pour quelle valeur de x la dérivée s’annule-t-elle ?","aide":"e^(−x) n’est jamais nul : il reste à résoudre 1 − x = 0.","type":"nombre"},{"enonce":"Quelle est la concentration maximale ? Arrondis au centième.","aide":"Calcule g(1) = 1 × e^(−1), avec ta calculatrice.","type":"nombre","unite":"mg/L"},{"enonce":"Quelle est l’équation de la tangente à la courbe au point d’abscisse 0 ?","aide":"y = g′(0)(x − 0) + g(0). Calcule g(0) et g′(0).","type":"choix","options":[{"id":"a","texte":"y = x"},{"id":"b","texte":"y = x + 1"},{"id":"c","texte":"y = 1"},{"id":"d","texte":"y = 0"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"Le sommet est au point d’abscisse **x = 1** (concentration 0,368 mg/L)."},{"cle":{"type":"choix","ids":["a"]},"explication":"g′(x) = 1 × e^(−x) + x × (−e^(−x)) = e^(−x) − x e^(−x) = **(1 − x) e^(−x)**."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"g′(x) = 0 équivaut à 1 − x = 0, donc **x = 1**. La dérivée est positive avant 1 et négative après : g est croissante puis décroissante."},{"cle":{"type":"nombre","valeur":0.37,"tolerance":0.005},"affichage":"0,37 mg/L","explication":"g(1) = e^(−1) ≈ 0,3679, soit **0,37 mg/L** au centième."},{"cle":{"type":"choix","ids":["a"]},"explication":"g(0) = 0 et g′(0) = (1 − 0) × e⁰ = 1 : la tangente est **y = x**."}]$ex$::jsonb),
  ('ae795625-7722-5c76-a1e5-9edcf501d0f8'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La tangente en un point de la courbe","competence":"lire-graphique","situation":"Nadia étudie la fonction f(x) = x² + x. Elle a tracé sa courbe et veut l’équation de la tangente au point A d’abscisse 1.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Courbe de f(x) = x² + x","categories":["−2","−1,5","−1","−0,5","0","0,5","1","1,5","2"],"series":[{"nom":"f(x)","valeurs":[2,0.75,0,-0.25,0,0.75,2,3.75,6],"teinte":"violet"}],"axeY":{"titre":"f(x)","min":-1,"max":6,"pas":1},"axeX":{"titre":"x"},"source":"Valeurs calculées pour l’exercice"},{"id":"rappel","type":"texte","genre":"consigne","titre":"Le rappel de cours","blocs":["La tangente en a a pour équation y = f′(a)(x − a) + f(a)."],"source":"Rappel de cours"}],"questions":[{"enonce":"Touche sur la courbe le point A d’abscisse 1.","aide":"Repère la graduation « 1 » sur l’axe des abscisses.","type":"zone","document":"courbe","multiple":false},{"enonce":"Calcule f(1).","aide":"Remplace x par 1 dans x² + x.","type":"nombre"},{"enonce":"Calcule f′(1), sachant que f′(x) = 2x + 1.","aide":"Remplace x par 1 dans 2x + 1.","type":"nombre"},{"enonce":"Quelle est l’équation de la tangente en A ?","aide":"y = f′(1)(x − 1) + f(1) : développe et simplifie.","type":"choix","options":[{"id":"a","texte":"y = 2x + 3"},{"id":"b","texte":"y = 3x + 2"},{"id":"c","texte":"y = 2x − 1"},{"id":"d","texte":"y = 3x − 1"}],"multiple":false}]}$ex$::jsonb,
