   $ex${"titre":"Le grattage et ses fréquences","competence":"programmer","situation":"Un jeu de grattage fait gagner avec une probabilité que l’on ne connaît pas par cœur. Mehdi a programmé une simulation : la fonction essai() renvoie 1 pour un ticket gagnant et 0 sinon, et frequence(n) donne la fréquence des gains sur n tickets.","documents":[{"id":"code","type":"texte","genre":"consigne","titre":"Le programme de Mehdi","blocs":["from random import random","def essai():","    if random() < 0.2:","        return 1","    return 0","def frequence(n):","    s = 0","    for i in range(n):","        s = s + essai()","    return s / n"],"source":"Programme écrit pour l’exercice"},{"id":"resultats","type":"tableau","titre":"Fréquences obtenues pour différentes tailles","colonnes":["n","10","100","1 000","10 000"],"lignes":[["frequence(n)","0,3","0,17","0,214","0,1987"]],"enteteLignes":true,"source":"Simulations réalisées pour l’exercice"}],"questions":[{"enonce":"Quelle est la probabilité de gagner programmée dans la fonction essai() ?","aide":"Le test random() < p est vrai avec la probabilité p.","type":"nombre"},{"enonce":"Pour n = 100, le programme renvoie 0,17. Combien de tickets gagnants cela représente-t-il ?","aide":"La fréquence vaut s ÷ n : retrouve s.","type":"nombre"},{"enonce":"Touche la fréquence la plus proche de la probabilité programmée.","aide":"Calcule l’écart entre chaque fréquence et 0,2.","type":"zone","document":"resultats","multiple":false},{"enonce":"Pour n = 10 000, on obtient 0,1987. Que peut-on dire ?","aide":"Relance mentalement la simulation : retrouverait-on exactement le même nombre ?","type":"choix","options":[{"id":"a","texte":"Cette fréquence estime la probabilité de gagner, sans la démontrer"},{"id":"b","texte":"Cette fréquence montre que le programme est faux car 0,1987 ≠ 0,2"},{"id":"c","texte":"Cette fréquence prouve que la probabilité de gagner vaut 0,1987"},{"id":"d","texte":"Cette fréquence devrait valoir exactement 0,2 à chaque simulation"}],"multiple":false}]}$ex$::jsonb,
