  ('f6f5e298-1a8e-59b5-af64-b30f7610eac3'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Que calcule la fonction mystere ?","competence":"raisonner","situation":"Sonia trouve une fonction dans le programme de son club d’informatique, sans commentaire. Pour savoir ce qu’elle calcule, elle suit son exécution pour n = 6, puis en tire une conclusion.","documents":[{"id":"fonction","type":"texte","genre":"consigne","titre":"La fonction mystere","blocs":["def mystere(n):","    s = 0","    for i in range(1, n + 1):","        if i % 2 == 0:","            s = s + i","    return s"],"source":"Programme écrit pour l’exercice"},{"id":"trace","type":"tableau","titre":"Trace de mystere(6)","colonnes":["i","1","2","3","4","5","6"],"lignes":[["s après le tour",0,2,2,"?",6,"?"]],"enteteLignes":true,"source":"Trace écrite pour l’exercice"}],"questions":[{"enonce":"Quelle est la valeur de s après le tour i = 4 (première case manquante) ?","aide":"i = 4 est pair : s augmente de 4.","type":"nombre"},{"enonce":"Quelle est la valeur renvoyée par mystere(6) (dernière case manquante) ?","aide":"i = 6 est pair ; i = 5 ne change pas s.","type":"nombre"},{"enonce":"Que calcule mystere(n) ?","aide":"Regarde quelles valeurs de i sont ajoutées à s : celles pour lesquelles i % 2 == 0.","type":"choix","options":[{"id":"a","texte":"La somme des entiers pairs de 1 à n"},{"id":"b","texte":"La somme des entiers impairs de 1 à n"},{"id":"c","texte":"La somme des entiers de 1 à n"},{"id":"d","texte":"Le nombre d’entiers pairs de 1 à n"}],"multiple":false},{"enonce":"Calcule mystere(100) sans exécuter le programme.","aide":"2 + 4 + … + 100 = 2 × (1 + 2 + … + 50) : utilise n(n + 1) ÷ 2.","type":"nombre"},{"enonce":"On remplace la dernière ligne « return s » par « print(s) ». Que se passe-t-il pour l’expression mystere(6) + 1 ?","aide":"print affiche une valeur, mais que renvoie alors la fonction ?","type":"choix","options":[{"id":"a","texte":"Il affiche 12 puis 13 : le calcul se fait sans aucune erreur"},{"id":"b","texte":"Il affiche 13 : print renvoie 12, qui s’additionne à 1 sans erreur"},{"id":"c","texte":"Rien ne s’affiche : print empêche tout calcul sur le résultat"},{"id":"d","texte":"Il affiche 12, puis une erreur : la fonction ne renvoie rien"}],"multiple":false}]}$ex$::jsonb,
