  ('f8997215-8985-5b89-a0b6-13e8a50fbfb9'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les abonnés de la chaîne de Camille","competence":"programmer","situation":"Camille a lancé sa chaîne vidéo avec 400 abonnés. Chaque mois, leur nombre augmente de 10 %, donc u(0) = 400 et u(n+1) = 1,1 × u(n). Elle écrit un programme pour savoir à partir de quel mois elle dépassera 600 abonnés.","documents":[{"id":"suivi","type":"tableau","titre":"Les premiers mois","colonnes":["Mois n","0","1","2","3","4"],"lignes":[["Abonnés u(n)","400","440","484","532,4","585,64"]],"enteteLignes":true,"source":"Valeurs calculées pour l’exercice"}],"questions":[{"enonce":"Touche la dernière case où le nombre d’abonnés est encore **inférieur à 600**.","aide":"Lis le tableau de gauche à droite et arrête-toi juste avant de dépasser 600.","type":"zone","document":"suivi","multiple":false},{"enonce":"Calcule u(5), arrondi à l’unité (nombre d’abonnés).","aide":"Multiplie u(4) par 1,1.","type":"nombre","unite":"abonnés"},{"enonce":"Quelle condition écrire après while pour que la boucle continue tant que le seuil n’est pas atteint ?","aide":"La condition est celle pour continuer : le contraire de ce qu’on attend.","type":"choix","options":[{"id":"a","texte":"u est supérieur à 600"},{"id":"b","texte":"u est inférieur à 600"},{"id":"c","texte":"u est égal à 600"},{"id":"d","texte":"n est inférieur à 600"}],"multiple":false},{"enonce":"Le programme part de n = 0 et u = 400, et ajoute 1 à n à chaque tour. Quelle valeur de n renvoie-t-il ?","aide":"Cherche le premier rang où le tableau (complété) dépasse 600.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c4"]},"explication":"Au mois 4, u(4) = 585,64 est encore sous 600 : c’est la dernière case avant le dépassement. Un algorithme de seuil s’arrête **dès que** la valeur franchit le seuil."},{"cle":{"type":"nombre","valeur":644,"tolerance":0.5},"affichage":"644 abonnés","explication":"u(5) = 585,64 × 1,1 = 644,204, soit **644** abonnés. Méthode : on passe d’un terme au suivant en multipliant par la raison."},{"cle":{"type":"choix","ids":["b"]},"explication":"On attend u > 600, donc on continue tant que **u < 600** (while u < 600). Avec la condition inverse, la boucle ne démarrerait même pas, puisque u(0) = 400."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"u(4) = 585,64 < 600 mais u(5) ≈ 644 > 600 : la boucle s’arrête avec **n = 5**. On relit toujours un algorithme à la main sur les premiers tours."}]$ex$::jsonb),
  ('f8997215-8985-5b89-a0b6-13e8a50fbfb9'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Approcher √3 avec la méthode de Newton","competence":"calculer","situation":"Salomé veut une valeur approchée de √3 sans toucher à la touche racine. Elle applique la méthode de Newton à f(x) = x² − 3, qui s’annule en √3, en partant de x₀ = 2. Son tableau de calcul est à moitié rempli.","documents":[{"id":"newton","type":"tableau","titre":"Méthode de Newton pour f(x) = x² − 3","colonnes":["n","xₙ","f(xₙ)","f′(xₙ)","xₙ₊₁"],"lignes":[["0","2","1","4","1,75"],["1","1,75","0,0625","?","?"]],"source":"Calculs écrits pour l’exercice"}],"questions":[{"enonce":"Touche la case qui montre que x₁ est déjà bien plus proche d’une solution que x₀.","aide":"Une solution de f(x) = 0 rend f(x) égal à 0 : cherche la valeur de f la plus proche de 0.","type":"zone","document":"newton","multiple":false},{"enonce":"Quelle est la dérivée de f(x) = x² − 3 ?","aide":"La dérivée de x² est 2x et celle d’une constante est 0.","type":"choix","options":[{"id":"a","texte":"f′(x) = x − 3"},{"id":"b","texte":"f′(x) = x²"},{"id":"c","texte":"f′(x) = 2x − 3"},{"id":"d","texte":"f′(x) = 2x"}],"multiple":false},{"enonce":"Complète la case manquante : calcule f′(x₁) pour x₁ = 1,75.","aide":"Utilise f′(x) = 2x avec x = 1,75.","type":"nombre"},{"enonce":"Calcule x₂ = x₁ − f(x₁) / f′(x₁), arrondi au dix-millième.","aide":"x₂ = 1,75 − 0,0625 ÷ 3,5. Calcule d’abord la division.","type":"nombre"},{"enonce":"Salomé essaie de partir de x₀ = 0. Que se passe-t-il ?","aide":"Regarde la formule : par quoi divise-t-on ? Que vaut f′(0) ?","type":"choix","options":[{"id":"a","texte":"Elle ne peut pas calculer x₁, car f′(0) = 0"},{"id":"b","texte":"Elle obtient x₁ = 3 sans difficulté"},{"id":"c","texte":"Elle trouve x₁ = 0 et la méthode s’arrête"},{"id":"d","texte":"Elle trouve directement x₁ = √3"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"f(x₀) = 1 mais f(x₁) = **0,0625** : on s’est beaucoup rapproché de 0, donc d’une solution de f(x) = 0."},{"cle":{"type":"choix","ids":["d"]},"explication":"On dérive terme à terme : (x²)′ = 2x et (−3)′ = 0, donc **f′(x) = 2x**."},{"cle":{"type":"nombre","valeur":3.5,"tolerance":0},"affichage":"3,5","explication":"f′(1,75) = 2 × 1,75 = **3,5**."},{"cle":{"type":"nombre","valeur":1.7321,"tolerance":0.0001},"affichage":"1,7321","explication":"0,0625 ÷ 3,5 ≈ 0,017857, donc x₂ = 1,75 − 0,017857 ≈ **1,7321**, qui est bien une valeur approchée de √3."},{"cle":{"type":"choix","ids":["a"]},"explication":"f′(0) = 2 × 0 = 0 : on diviserait par zéro. La méthode **exige f′(xₙ) non nul** — c’est pourquoi on choisit un point de départ adapté."}]$ex$::jsonb),
  ('f8997215-8985-5b89-a0b6-13e8a50fbfb9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Euler contre l’exponentielle","competence":"modeliser","situation":"Pour construire la fonction exponentielle point par point, Inès utilise la méthode d’Euler avec un pas h = 0,25 : y(0) = 1 et y(k+1) = (1 + h) × y(k). Elle s’arrête à x = 1, après 4 pas, et compare son résultat à la vraie courbe.","documents":[{"id":"pas","type":"tableau","titre":"Les pas de la méthode d’Euler","colonnes":["Pas k","0","1","2","3","4"],"lignes":[["Abscisse x","0","0,25","0,5","0,75","1"],["y(k)","1","1,25","?","?","?"]],"enteteLignes":true},{"id":"comparaison","type":"graphique","forme":"courbe","titre":"Euler (h = 0,25) et exponentielle","categories":["0","0,25","0,5","0,75","1"],"series":[{"nom":"Méthode d’Euler","valeurs":[1,1.25,1.5625,1.9531,2.4414],"teinte":"violet"},{"nom":"Exponentielle","valeurs":[1,1.284,1.6487,2.117,2.7183],"teinte":"turquoise"}],"axeY":{"titre":"Valeur","min":1,"max":3,"pas":0.5},"axeX":{"titre":"x"},"valeurs":false,"source":"Valeurs calculées et arrondies pour l’exercice"}],"questions":[{"enonce":"Calcule y(2) dans la ligne du tableau.","aide":"y(2) = 1,25 × y(1).","type":"nombre"},{"enonce":"Calcule y(4), arrondi au centième : c’est la valeur d’Euler pour x = 1.","aide":"Continue : y(3) = 1,25 × y(2), puis y(4) = 1,25 × y(3).","type":"nombre"},{"enonce":"Touche l’abscisse où l’écart entre les deux courbes est le **plus grand**.","aide":"Compare la distance verticale entre les deux courbes à chaque abscisse.","type":"zone","document":"comparaison","multiple":false},{"enonce":"Pour x = 1, quel est l’écart entre l’exponentielle (2,7183) et ta valeur d’Euler, arrondi au centième ?","aide":"Soustrais la valeur d’Euler à celle de l’exponentielle.","type":"nombre"},{"enonce":"Comment Inès peut-elle réduire cet écart ?","aide":"Sur un petit pas, l’approximation f(x + h) ≈ f(x) + h f′(x) est plus juste.","type":"choix","options":[{"id":"a","texte":"En prenant un pas h plus petit"},{"id":"b","texte":"En remplaçant 1 + h par 1 − h"},{"id":"c","texte":"En prenant un pas h plus grand"},{"id":"d","texte":"En changeant la valeur de y(0)"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":1.5625,"tolerance":0},"affichage":"1,5625","explication":"y(2) = 1,25 × 1,25 = **1,5625**. À chaque pas on multiplie par 1 + h = 1,25."},{"cle":{"type":"nombre","valeur":2.44,"tolerance":0.005},"affichage":"2,44","explication":"y(3) = 1,953125 puis y(4) = 2,44140625, soit **2,44** : une valeur approchée de e."},{"cle":{"type":"zone","ids":["k4"]},"explication":"Les deux courbes partent du même point, puis s’écartent de plus en plus : l’écart est maximal pour **x = 1**."},{"cle":{"type":"nombre","valeur":0.28,"tolerance":0.005},"affichage":"0,28","explication":"2,7183 − 2,4414 = 0,2769, soit environ **0,28**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Plus le pas est petit, plus l’approximation de chaque pas est précise : un **pas h plus petit** donne en général une meilleure approximation."}]$ex$::jsonb),
