  ('34a7462d-ef4f-543f-b711-f9b0c3869a32'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les élections de délégués : points ou pourcentage ?","competence":"raisonner","situation":"Le journal du lycée commente la participation aux élections des délégués. Sana relit l’article et le compare au graphique : elle a un doute sur un chiffre.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Participation aux élections (en %)","categories":["2021","2022","2023","2024"],"series":[{"nom":"Participation","valeurs":[40,44,55,44],"teinte":"violet"}],"axeY":{"titre":"Participation","unite":"%","min":30,"max":60,"pas":10},"axeX":{"titre":"Année"},"valeurs":false,"source":"Chiffres inventés pour l’exercice"},{"id":"article","type":"texte","genre":"article","titre":"Au journal du lycée","blocs":["Les élèves se sont mobilisés : la participation aux élections des délégués bondit de 11 % entre 2022 et 2023, avant de retomber l’année suivante."],"auteur":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche l’année où la participation a le **plus augmenté** par rapport à l’année précédente.","aide":"Compare la montée de la courbe d’une année à la suivante.","type":"zone","document":"courbe","multiple":false},{"enonce":"De combien de **points de pourcentage** la participation augmente-t-elle de 2022 à 2023 ?","aide":"Soustrais les deux taux de participation.","type":"nombre","unite":"points"},{"enonce":"Quel est le **taux d’évolution** de la participation entre 2022 et 2023, en pourcentage ?","aide":"taux = (valeur finale − valeur initiale) / valeur initiale, avec 44 et 55.","type":"nombre","unite":"%"},{"enonce":"Que reproche-t-on à l’article quand il écrit « bondit de 11 % » ?","aide":"Compare avec tes deux calculs précédents : 11 est-il un nombre de points ou un taux ?","type":"choix","options":[{"id":"a","texte":"Il oublie que la participation a baissé en 2024"},{"id":"b","texte":"Il donne un taux supérieur à 100 %"},{"id":"c","texte":"Il compare 2021 et 2023 au lieu de 2022 et 2023"},{"id":"d","texte":"Il confond une hausse de 11 points avec une hausse de 11 %"}],"multiple":false},{"enonce":"La participation retombe de 55 % à 44 % en 2024. De combien de pour cent baisse-t-elle ? (nombre positif)","aide":"Divise la baisse (11 points) par la valeur de départ de cette évolution.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"De 44 % à 55 %, la hausse est de 11 points : c’est la plus forte, en **2023**."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11 points","explication":"55 − 44 = **11 points**."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 %","explication":"(55 − 44) ÷ 44 = 11 ÷ 44 = 0,25, soit **+25 %**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La hausse est de 11 **points**, mais de **25 %** en taux d’évolution. L’article mélange les deux."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 %","explication":"(44 − 55) ÷ 55 = −0,2 : une baisse de **20 %**. C’est le taux réciproque d’une hausse de 25 %."}]$ex$::jsonb),
  ('c7e0ae53-7f58-5d9f-8d9c-17146318b0cf'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le contrôle corrigé d’Anaïs","competence":"calculer","situation":"Anaïs a fait quatre calculs d’automatismes sans calculatrice. Son professeur lui demande de retrouver ses erreurs avant de les corriger.","documents":[{"id":"copie","type":"tableau","titre":"Les résultats d’Anaïs","colonnes":["Calcul","Résultat d’Anaïs"],"lignes":[["3/4 + 1/8","4/12"],["2/3 × 3/4","1/2"],["10² × 10³","10⁵"],["(x + 2)²","x² + 4"]],"enteteLignes":true,"source":"Calculs écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux** résultats faux.","aide":"Refais chaque calcul de tête : 10² × 10³ s’obtient en additionnant les exposants.","type":"zone","document":"copie","multiple":true},{"enonce":"Calcule 3/4 + 1/8. Tu peux répondre par une fraction ou un décimal.","aide":"Mets les deux fractions sur le même dénominateur : 3/4 = …/8.","type":"nombre"},{"enonce":"Quel est le développement de (x + 2)² ?","aide":"Utilise (a + b)² = a² + 2ab + b² avec a = x et b = 2.","type":"choix","options":[{"id":"a","texte":"x² + 4x + 4"},{"id":"b","texte":"x² + 4"},{"id":"c","texte":"x² + 2x + 4"},{"id":"d","texte":"x² + 2x + 2"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r3c0"]},"explication":"3/4 + 1/8 ≠ 4/12 et (x + 2)² ≠ x² + 4. Les deux autres sont justes : 2/3 × 3/4 = 6/12 = 1/2 et 10² × 10³ = 10⁵."},{"cle":{"type":"nombre","valeur":0.875,"tolerance":0},"affichage":"0,875","explication":"3/4 = 6/8 donc 6/8 + 1/8 = 7/8 = **0,875**. On additionne des fractions de même dénominateur, pas les numérateurs et les dénominateurs entre eux."},{"cle":{"type":"choix","ids":["a"]},"explication":"(x + 2)² = x² + 2 × x × 2 + 2² = **x² + 4x + 4**. Le double produit 4x ne disparaît jamais."}]$ex$::jsonb),
  ('c7e0ae53-7f58-5d9f-8d9c-17146318b0cf'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Lyon–Marseille en train","competence":"calculer","situation":"Lina prend le train Lyon–Marseille. Elle lit la fiche horaire sur le quai et veut en tirer la vitesse moyenne du train, d’abord en km/h puis en m/s.","documents":[{"id":"horaires","type":"fiche","modele":"horaires","entete":"Train Lyon → Marseille","sousTitre":"Fiche du voyage","emoji":"🚆","lignes":[{"texte":"Départ de Lyon","valeur":"9 h 15","id":"z1"},{"texte":"Arrivée à Marseille","valeur":"11 h 00","id":"z2"},{"separateur":true},{"texte":"Distance parcourue","valeur":"189 km","id":"z3"}],"pied":"Horaires imaginés pour l’exercice","teinte":"bleu"}],"questions":[{"enonce":"Touche la ligne qui donne l’heure de fin du voyage.","aide":"Cherche l’heure d’arrivée.","type":"zone","document":"horaires","multiple":false},{"enonce":"Quelle est la durée du trajet, exprimée en heures sous forme décimale ?","aide":"De 9 h 15 à 11 h 00, combien d’heures et de minutes ? Et 45 min, quelle fraction d’heure ?","type":"nombre","unite":"h"},{"enonce":"Quelle est la vitesse moyenne du train, en km/h ?","aide":"v = d / t, avec d = 189 km et t = 1,75 h.","type":"nombre","unite":"km/h"},{"enonce":"Convertis cette vitesse en m/s.","aide":"Pour passer de km/h à m/s, on divise par 3,6.","type":"nombre","unite":"m/s"},{"enonce":"Si le train roulait à 126 km/h sur la même distance, combien de minutes durerait le trajet ?","aide":"On isole t dans v = d / t : t = d / v.","type":"nombre","unite":"min"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"L’arrivée est à **11 h 00**."},{"cle":{"type":"nombre","valeur":1.75,"tolerance":0},"affichage":"1,75 h","explication":"De 9 h 15 à 11 h 00, il s’écoule 1 h 45 min. 45 min = 3/4 d’heure = 0,75 h : la durée est **1,75 h**."},{"cle":{"type":"nombre","valeur":108,"tolerance":0},"affichage":"108 km/h","explication":"v = 189 ÷ 1,75 = **108 km/h**. Contrôle d’ordre de grandeur : 190 ÷ 2 ≈ 95, donc le résultat est plausible."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 m/s","explication":"108 ÷ 3,6 = **30 m/s** (30 m par seconde, soit 108 km par heure)."},{"cle":{"type":"nombre","valeur":90,"tolerance":0},"affichage":"90 min","explication":"t = d ÷ v = 189 ÷ 126 = 1,5 h, soit **90 minutes**."}]$ex$::jsonb),
  ('c7e0ae53-7f58-5d9f-8d9c-17146318b0cf'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le terrain remodelé","competence":"modeliser","situation":"Karim possède un terrain carré de côté x (en mètres). Pour un projet de potager, il en retire une bande de 3 m sur un côté et en ajoute une de 3 m sur le côté voisin : le terrain devient un rectangle dont l’aire vaut 40 m².","documents":[{"id":"plan","type":"figure","titre":"Le nouveau terrain (figure non à l’échelle)","cadre":{"xmin":0,"xmax":11,"ymin":0,"ymax":5},"quadrillage":false,"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":10,"y":1,"position":"se"},{"id":"C","x":10,"y":4,"position":"ne"},{"id":"D","x":1,"y":4,"position":"no"}],"segments":[{"de":"A","a":"B","longueur":"x + 3"},{"de":"B","a":"C","longueur":"x − 3"}],"polygones":[{"sommets":["A","B","C","D"],"teinte":"violet","motif":"clair"}],"angles":[{"sommet":"A","de":"B","a":"D","droit":true}],"source":"Figure dessinée pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Karim","emoji":"👦","cote":"gauche"},{"nom":"Léa","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Karim","texte":"J’ai résolu x² = 49 : je trouve x = 7 ou x = −7."},{"qui":"Léa","texte":"Alors il y a deux terrains possibles ?"}]}],"questions":[{"enonce":"Quelle expression donne l’aire du nouveau rectangle ?","aide":"L’aire d’un rectangle est longueur × largeur.","type":"choix","options":[{"id":"a","texte":"La somme (x + 3) + (x − 3)"},{"id":"b","texte":"Le produit (x + 3) × (x − 3)"},{"id":"c","texte":"Le double de la somme des deux côtés"},{"id":"d","texte":"Le carré x² diminué de 3"}],"multiple":false},{"enonce":"Quel est le développement de (x + 3)(x − 3) ?","aide":"C’est une identité remarquable du type (a + b)(a − b).","type":"choix","options":[{"id":"a","texte":"x² plus 9"},{"id":"b","texte":"x² moins 9"},{"id":"c","texte":"x² moins 6"},{"id":"d","texte":"x² moins 6x plus 9"}],"multiple":false},{"enonce":"Résous x² − 9 = 40 avec x > 0 : que vaut x ?","aide":"Ajoute 9 aux deux membres, puis cherche le nombre positif dont le carré est 49.","type":"nombre","unite":"m"},{"enonce":"Pourquoi Karim élimine-t-il la solution x = −7 ?","aide":"Relis l’énoncé : que représente x ?","type":"choix","options":[{"id":"a","texte":"Parce que (−7)² ne vaut pas 49"},{"id":"b","texte":"Parce que x doit être supérieur à 10"},{"id":"c","texte":"Parce que x est une longueur, donc positive"},{"id":"d","texte":"Parce que −7 est un nombre impair"}],"multiple":false},{"enonce":"Quel est le périmètre du nouveau terrain ?","aide":"Calcule les deux côtés avec x = 7, puis double leur somme.","type":"nombre","unite":"m"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Aire = longueur × largeur = **(x + 3)(x − 3)**. La somme ou le double de la somme donneraient un périmètre."},{"cle":{"type":"choix","ids":["b"]},"explication":"(a + b)(a − b) = a² − b², donc (x + 3)(x − 3) = **x² − 9** (x² moins 9)."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 m","explication":"x² − 9 = 40 donne x² = 49, donc x = 7 ou x = −7. Comme x est une longueur, **x = 7**."},{"cle":{"type":"choix","ids":["c"]},"explication":"(−7)² = 49 convient pour l’équation, mais x est le côté d’un carré : une longueur ne peut pas être négative. On garde **x = 7**."},{"cle":{"type":"nombre","valeur":28,"tolerance":0},"affichage":"28 m","explication":"Longueur : 7 + 3 = 10 m. Largeur : 7 − 3 = 4 m. Périmètre : 2 × (10 + 4) = **28 m**. Contrôle : 10 × 4 = 40 m², l’aire annoncée."}]$ex$::jsonb),
