   $ex${"titre":"Le club de théâtre du lycée","competence":"calculer","situation":"Le lycée compte 160 élèves en Première. Le professeur de théâtre a dressé un tableau croisé des élèves selon leur sexe et leur inscription au club. On choisit un élève au hasard ; F désigne « c’est une fille » et T « l’élève fait du théâtre ».","documents":[{"id":"croise","type":"tableau","titre":"Les élèves de Première et le théâtre","colonnes":["Élèves","Théâtre","Pas de théâtre","Total"],"lignes":[["Filles","36","54","90"],["Garçons","14","56","70"],["Total","50","110","160"]],"enteteLignes":true,"source":"Effectifs inventés pour l’exercice"}],"questions":[{"enonce":"Touche la case qui donne le nombre de filles qui font du théâtre.","aide":"Croise la ligne « Filles » et la colonne « Théâtre ».","type":"zone","document":"croise","multiple":false},{"enonce":"Calcule P(F ∩ T) : la probabilité que l’élève soit une fille et fasse du théâtre.","aide":"Parmi **tous** les élèves : effectif de « fille et théâtre » divisé par l’effectif total.","type":"nombre"},{"enonce":"Calcule la probabilité que l’élève fasse du théâtre sachant que c’est une fille.","aide":"Le mot « sachant » restreint la population : on ne regarde que les filles.","type":"nombre"},{"enonce":"Quelle fraction donne la probabilité que l’élève soit une fille, sachant qu’il fait du théâtre ?","aide":"La population restreinte est celle qui suit « sachant ». Combien d’élèves font du théâtre ?","type":"choix","options":[{"id":"a","texte":"36 / 50"},{"id":"b","texte":"36 / 160"},{"id":"c","texte":"36 / 90"},{"id":"d","texte":"50 / 160"}],"multiple":false},{"enonce":"Calcule la probabilité que l’élève ne fasse pas de théâtre.","aide":"P(non T) = 1 − P(T), ou lis directement l’effectif de la colonne « Pas de théâtre ».","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"La case à l’intersection est **36** : 36 filles font du théâtre."},{"cle":{"type":"nombre","valeur":0.225,"tolerance":0},"affichage":"0,225","explication":"P(F ∩ T) = 36 ÷ 160 = **0,225**. Le dénominateur est le total, 160."},{"cle":{"type":"nombre","valeur":0.4,"tolerance":0},"affichage":"0,4","explication":"On se restreint aux 90 filles : 36 ÷ 90 = **0,4**."},{"cle":{"type":"choix","ids":["a"]},"explication":"On se restreint aux 50 élèves du club : 36 filles sur 50, soit **36 / 50** = 0,72."},{"cle":{"type":"nombre","valeur":0.6875,"tolerance":0},"affichage":"0,6875","explication":"P(T) = 50 ÷ 160 = 0,3125, donc P(non T) = 1 − 0,3125 = **0,6875** (= 110 ÷ 160)."}]$ex$::jsonb),
  ('205ecc6c-c6c0-54ed-9d7e-c8c9d107fa62'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux classes, une même médiane","competence":"raisonner","situation":"Deux classes de Première ont passé le même contrôle de maths. Les profs résument chaque série par cinq indicateurs. Mia affirme que les deux classes sont « pareilles », puisque leur médiane est identique.","documents":[{"id":"indic","type":"tableau","titre":"Résultats du contrôle (sur 20)","colonnes":["Indicateur","Classe A","Classe B"],"lignes":[["Minimum","4","7"],["Q₁","8","9"],["Médiane","11","11"],["Q₃","14","12"],["Maximum","18","15"]],"enteteLignes":true,"source":"Notes inventées pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Les deux classes ont 11 de médiane : elles ont donc les mêmes résultats !"},{"qui":"Hugo","texte":"Pas si vite…"}]}],"questions":[{"enonce":"Touche la valeur Q₃ de la classe A : la note en dessous de laquelle se trouvent au moins 75 % de ses élèves.","aide":"Q₃ est le troisième quartile : cherche la ligne qui porte ce nom, colonne de la classe A.","type":"zone","document":"indic","multiple":false},{"enonce":"Calcule l’écart interquartile de la classe A.","aide":"écart interquartile = Q₃ − Q₁.","type":"nombre"},{"enonce":"Calcule l’écart interquartile de la classe B.","aide":"Même formule : Q₃ − Q₁.","type":"nombre"},{"enonce":"Que peut-on dire de la dispersion des notes des deux classes ?","aide":"Compare les écarts interquartiles : le plus petit correspond à la série la plus resserrée.","type":"choix","options":[{"id":"a","texte":"Les notes de la classe B sont plus regroupées"},{"id":"b","texte":"Les deux classes ont la même dispersion"},{"id":"c","texte":"Les notes de la classe A sont plus regroupées"},{"id":"d","texte":"On ne peut rien dire sans les moyennes"}],"multiple":false},{"enonce":"Que répondre à Mia, qui dit « même médiane, donc mêmes résultats » ?","aide":"Relis les autres lignes du tableau : minimum, maximum, quartiles…","type":"choix","options":[{"id":"a","texte":"Elle a raison, mais seulement si Q₁ est identique"},{"id":"b","texte":"Elle a raison : la médiane résume toute la série"},{"id":"c","texte":"La médiane ne dit rien de la dispersion : les classes diffèrent"},{"id":"d","texte":"Elle a tort : les médianes sont en réalité différentes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Le troisième quartile de la classe A vaut **14**."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"14 − 8 = **6**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"12 − 9 = **3**."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’écart interquartile de B (3) est plus petit que celui de A (6) : les notes de **B sont plus regroupées autour de la médiane**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Une médiane partage la série en deux moitiés mais **ne mesure pas la dispersion** : ici les écarts interquartiles (6 et 3) et les étendues (14 et 8) diffèrent."}]$ex$::jsonb),
  ('3ed01545-72d3-5b02-8bda-76c1948db04f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Chloé prépare l’épreuve de juin","competence":"analyser-document","situation":"Chloé est en Première et passera l’épreuve anticipée de mathématiques en juin. Elle a recopié les principales informations de l’épreuve sur une fiche.","documents":[{"id":"fiche","type":"fiche","modele":"affiche","entete":"L’épreuve anticipée de maths","sousTitre":"Ce que Chloé doit retenir","emoji":"📝","lignes":[{"texte":"Durée","valeur":"2 heures","id":"z1"},{"texte":"Note totale","valeur":"20 points"},{"separateur":true},{"texte":"Partie 1 — Automatismes","valeur":"6 points","id":"z2"},{"texte":"Partie 2 — Exercices","valeur":"14 points","id":"z3"},{"separateur":true},{"texte":"Calculatrice","valeur":"interdite","id":"z4"}],"pied":"Fiche rédigée pour l’exercice","teinte":"violet"}],"questions":[{"enonce":"Touche la ligne qui indique combien de temps dure l’épreuve.","aide":"Cherche la ligne « Durée ».","type":"zone","document":"fiche","multiple":false},{"enonce":"Quelle part de la note totale représentent les automatismes ? Réponds en pourcentage.","aide":"proportion = partie / tout : 6 points sur 20.","type":"nombre","unite":"%"},{"enonce":"Chloé vise 20 minutes pour les automatismes. Combien de minutes lui reste-t-il pour la partie exercices ?","aide":"2 heures = 120 minutes.","type":"nombre","unite":"min"},{"enonce":"Chloé veut utiliser sa calculatrice pour la partie exercices. Est-ce permis ?","aide":"Relis la ligne « Calculatrice » de la fiche.","type":"choix","options":[{"id":"a","texte":"Oui, avec le mode examen activé"},{"id":"b","texte":"Oui, pour la partie exercices uniquement"},{"id":"c","texte":"Oui, pour la partie automatismes uniquement"},{"id":"d","texte":"Non : elle est interdite pendant toute l’épreuve"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"L’épreuve dure **2 heures**."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 %","explication":"6 ÷ 20 = 0,3, soit **30 %** de la note : une partie courte, mais bien rentable."},{"cle":{"type":"nombre","valeur":100,"tolerance":0},"affichage":"100 min","explication":"2 h = 120 min, et 120 − 20 = **100 minutes** pour les exercices."},{"cle":{"type":"choix","ids":["d"]},"explication":"La fiche l’indique : la calculatrice est **interdite pendant toute l’épreuve**, automatismes comme exercices."}]$ex$::jsonb),
  ('3ed01545-72d3-5b02-8bda-76c1948db04f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le planning de Yanis","competence":"raisonner","situation":"Yanis a préparé un planning pour les 2 heures de l’épreuve. Il hésite à y ajouter un temps de relecture.","documents":[{"id":"planning","type":"tableau","titre":"Le planning de Yanis","colonnes":["Étape","Durée (min)"],"lignes":[["Automatismes","30"],["Exercice 1","40"],["Exercice 2","40"],["Relecture","?"]],"enteteLignes":true,"source":"Planning imaginé pour l’exercice"}],"questions":[{"enonce":"L’épreuve dure 2 h. Quelle durée Yanis peut-il consacrer à la relecture ?","aide":"Additionne les durées connues et retire-les de 120 minutes.","type":"nombre","unite":"min"},{"enonce":"Quel pourcentage de la durée de l’épreuve Yanis consacre-t-il aux automatismes ?","aide":"proportion = partie / tout : 30 min sur 120 min.","type":"nombre","unite":"%"},{"enonce":"Les automatismes valent 6 points sur 20. Quel pourcentage de la note représentent-ils ?","aide":"Compare 6 à 20.","type":"nombre","unite":"%"},{"enonce":"Que peut-on dire du choix de Yanis pour les automatismes ?","aide":"Compare la part du temps et la part des points rapportés.","type":"choix","options":[{"id":"a","texte":"Il devrait y passer plus de temps que sur les exercices"},{"id":"b","texte":"Il y passe 25 % du temps pour 30 % des points : c’est rentable"},{"id":"c","texte":"Il y passe 30 % du temps pour 25 % des points : c’est coûteux"},{"id":"d","texte":"Il y passe autant de temps que de points : c’est neutre"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 min","explication":"30 + 40 + 40 = 110 minutes, donc il reste 120 − 110 = **10 minutes** de relecture."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 %","explication":"30 ÷ 120 = 1/4 = **25 %** du temps."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 %","explication":"6 ÷ 20 = 0,3, soit **30 %** des points."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les automatismes rapportent **30 % des points** en n’occupant que **25 % du temps** : c’est la partie la plus rentable de l’épreuve, il ne faut pas s’y éterniser."}]$ex$::jsonb),
  ('3ed01545-72d3-5b02-8bda-76c1948db04f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le brouillon de Sacha","competence":"raisonner","situation":"Sacha a répondu aux questions d’automatismes d’un sujet d’entraînement, mais certains résultats ne sont pas vraisemblables. Un bon réflexe de l’épreuve est de contrôler l’ordre de grandeur avant de rendre sa copie.","documents":[{"id":"copie","type":"tableau","titre":"Les réponses de Sacha","colonnes":["Question","Réponse de Sacha"],"lignes":[["Un prix de 40 € baisse de 25 % : nouveau prix ?","50 €"],["Probabilité de tirer une carte rouge dans un jeu de 32 cartes ?","1/2"],["Calcule 49 × 21.","10 290"],["18 filles sur 24 élèves : quelle proportion de filles ?","1,33"]],"enteteLignes":true,"source":"Réponses inventées pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Sacha","emoji":"🧑","cote":"gauche"},{"nom":"Prof","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Sacha","texte":"Je bloque sur la question 2 de l’exercice 1 et je perds un temps fou."},{"qui":"Prof","texte":"Le résultat est donné dans l’énoncé : utilise-le pour la suite."}]}],"questions":[{"enonce":"Touche les **trois** réponses invraisemblables.","aide":"Un prix après une baisse ne peut pas monter, 49 × 21 est proche de 50 × 20, et une proportion ne dépasse jamais 1.","type":"zone","document":"copie","multiple":true},{"enonce":"Corrige la première réponse : quel est le prix de 40 € après une baisse de 25 % ?","aide":"Le coefficient d’une baisse de 25 % est 0,75. Ou : retire le quart de 40.","type":"nombre","unite":"€"},{"enonce":"Corrige la troisième réponse : combien vaut 49 × 21 ?","aide":"49 × 21 = 49 × 20 + 49.","type":"nombre"},{"enonce":"Corrige la dernière réponse : quelle est la proportion de filles, sous forme décimale ?","aide":"Simplifie 18 / 24 par 6.","type":"nombre"},{"enonce":"Que fait Sacha d’une question d’exercice qui résiste, d’après le conseil de son prof ?","aide":"Relis le message de Prof : le résultat est donné dans l’énoncé.","type":"choix","options":[{"id":"a","texte":"Elle passe tout l’exercice et n’y revient pas"},{"id":"b","texte":"Elle abandonne la copie à ce moment"},{"id":"c","texte":"Elle devine un résultat approximatif"},{"id":"d","texte":"Elle admet le résultat donné et continue"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r2c0","r3c0"]},"explication":"Après une baisse le prix ne peut pas augmenter ; 49 × 21 doit être proche de 1 000, pas de 10 000 ; une proportion est toujours inférieure ou égale à 1."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 €","explication":"40 × 0,75 = **30 €** (on retire 10 €, le quart de 40)."},{"cle":{"type":"nombre","valeur":1029,"tolerance":0},"affichage":"1029","explication":"49 × 20 = 980 et 980 + 49 = **1 029**, proche de l’estimation 50 × 20 = 1 000."},{"cle":{"type":"nombre","valeur":0.75,"tolerance":0},"affichage":"0,75","explication":"18 ÷ 24 = 3/4 = **0,75**. Le résultat de Sacha, plus grand que 1, était impossible pour une proportion."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les questions s’enchaînent : quand l’une résiste, on **admet son résultat** (souvent donné) et on continue, car la suite en dépend rarement autrement."}]$ex$::jsonb),
  ('49a68504-975d-5e98-9139-3bfdfa5f34f3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux interprètes, une partition","competence":"lire-tableau","situation":"Deux pianistes jouent le même passage d’une même partition. Camille compare leurs choix dans un tableau et en déduit ce que décide un interprète.","documents":[{"id":"comp","type":"tableau","titre":"Le même passage, deux interprétations","colonnes":["Critère","Interprète A","Interprète B"],"lignes":[["Tempo (pulsations par minute)",60,80],["Durée du passage","3 min 00 s","2 min 15 s"],["Nuances","Très douces, peu de relief","Contrastées : le thème ressort"],["Phrasé","Notes très liées","Notes plus détachées"]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"}],"questions":[{"enonce":"Touche **le tempo le plus rapide**.","aide":"Plus il y a de pulsations par minute, plus la musique va vite.","type":"zone","document":"comp","multiple":false},{"enonce":"De combien de secondes la version B est-elle plus courte que la version A ?","aide":"Passe les deux durées en secondes avant de soustraire : 3 min = 180 s.","type":"nombre","unite":"secondes"},{"enonce":"Relie chaque choix de l’interprète à ce qu’il change à l’écoute.","aide":"Le tableau compare le tempo, les nuances et le phrasé : relie chaque ligne à son effet.","type":"association","gauche":[{"id":"g0","texte":"Le tempo"},{"id":"g1","texte":"Les nuances"},{"id":"g2","texte":"Le phrasé"},{"id":"g3","texte":"L’instrument"}],"droite":[{"id":"d0","texte":"Le sens : où la phrase respire"},{"id":"d1","texte":"La couleur, l’équilibre, la puissance"},{"id":"d2","texte":"L’énergie, la respiration de la phrase"},{"id":"d3","texte":"Le relief, ce qui passe au premier plan"}]}]}$ex$::jsonb,
