   $ex${"titre":"Écouter deux fois, comparer","competence":"lire-graphique","situation":"Inès prépare une écoute active : elle compare le tempo de deux interprétations d’un même morceau, section par section. Elle note aussi comment organiser son écoute et comment en parler.","documents":[{"id":"tempo","type":"graphique","forme":"courbe","titre":"Tempo de deux interprétations","categories":["Début","Thème","Reprise","Fin"],"series":[{"nom":"Interprétation A","valeurs":[80,80,80,70],"teinte":"violet"},{"nom":"Interprétation B","valeurs":[72,84,66,50],"teinte":"corail"}],"axeY":{"titre":"Tempo","unite":"pulsations/min","min":40,"max":90,"pas":10},"axeX":{"titre":"Section du morceau"},"source":"Valeurs imaginées pour l’exercice"},{"id":"notes","type":"texte","genre":"article","titre":"Les notes d’Inès","auteur":"Notes écrites pour l’exercice","blocs":["Je compare deux interprétations du même passage : c’est le raccourci le plus efficace pour voir ce que décide un interprète.","Dans l’interprétation B, la dernière section est presque suspendue, alors qu’A garde presque le même tempo jusqu’au bout."],"source":"Notes écrites pour l’exercice"}],"questions":[{"enonce":"Touche **la section où les deux interprétations diffèrent le plus**.","aide":"Pour chaque section, calcule l’écart entre les deux tempos.","type":"zone","document":"tempo","multiple":false},{"enonce":"De combien de pulsations par minute l’interprétation B ralentit-elle entre la reprise et la fin ?","aide":"Lis la courbe de B pour la reprise, puis pour la fin.","type":"nombre","unite":"pulsations/min"},{"enonce":"Quelle phrase relève d’une écoute active, avec des mots d’analyse et non de goût ?","aide":"Une phrase d’analyse s’appuie sur ce qu’on entend (tempo, section), pas sur ce qu’on aime.","type":"choix","options":[{"id":"a","texte":"B ralentit nettement à la fin : la phrase paraît suspendue"},{"id":"b","texte":"J’aime moins la version B que la version A"},{"id":"c","texte":"La version B est tout simplement la meilleure"},{"id":"d","texte":"B est triste, car le pianiste devait être triste"}],"multiple":false},{"enonce":"Range chaque geste d’écoute : avant, pendant ou après ?","aide":"Avant : se préparer. Pendant : repérer les retours et les ruptures. Après : raconter.","type":"categories","categories":[{"id":"c0","texte":"Avant"},{"id":"c1","texte":"Pendant"},{"id":"c2","texte":"Après"}],"items":[{"id":"i0","texte":"Raconter ce que j’ai entendu avec des mots d’analyse"},{"id":"i1","texte":"Noter une rupture"},{"id":"i2","texte":"Choisir un repère : instrument, forme, retour de thème"},{"id":"i3","texte":"Me demander ce que je vais chercher"},{"id":"i4","texte":"Noter un retour du thème"},{"id":"i5","texte":"Comparer mes notes avec celles d’un camarade"}]}]}$ex$::jsonb,
