   $ex${"titre":"Trois fins de phrase","competence":"analyser-document","situation":"Lina écoute trois phrases d’une chanson et note, pour chacune, comment elle se termine. Elle veut mettre un nom sur ce qu’elle ressent à la fin de chaque phrase.","documents":[{"id":"notes","type":"tableau","titre":"Le carnet d’écoute de Lina","colonnes":["Phrase","Ce que j’entends à la fin"],"lignes":[["Phrase 1","La dominante puis la tonique : la phrase se ferme"],["Phrase 2","On s’arrête sur la dominante : la phrase reste ouverte"],["Phrase 3","La dominante, puis un autre degré que la tonique : surprise"]],"enteteLignes":true,"source":"Notes d’écoute imaginées pour l’exercice"}],"questions":[{"enonce":"Touche **la phrase qui paraît achevée** à l’oreille.","aide":"Une phrase achevée se termine par la tonique, après la dominante.","type":"zone","document":"notes","multiple":false},{"enonce":"Donne à chaque fin de phrase le nom de sa cadence.","aide":"Parfaite : dominante puis tonique. Suspensive : on s’arrête sur la dominante. Rompue : un autre degré.","type":"association","gauche":[{"id":"g0","texte":"Phrase 1"},{"id":"g1","texte":"Phrase 2"},{"id":"g2","texte":"Phrase 3"}],"droite":[{"id":"d0","texte":"Cadence suspensive"},{"id":"d1","texte":"Cadence rompue"},{"id":"d2","texte":"Cadence parfaite"}]},{"enonce":"Quel effet produit la cadence de la phrase 3 ?","aide":"La dominante promet la tonique, mais elle ne vient pas.","type":"choix","options":[{"id":"a","texte":"L’achèvement : la phrase se ferme"},{"id":"b","texte":"L’attente : la phrase reste ouverte"},{"id":"c","texte":"La surprise : l’attente est déjouée"},{"id":"d","texte":"Un silence qui annonce la fin du morceau"}],"multiple":false}]}$ex$::jsonb,
