   $ex${"titre":"Le moment où tout change","competence":"analyser-document","situation":"Au concours d’analyse, Sofia écoute « Lever de lune », une pièce imaginée pour l’exercice. Elle a noté l’intensité (de 1, très doux, à 5, très fort) puis rempli un journal d’écoute. Elle cherche le moment qui révèle l’intention du compositeur.","documents":[{"id":"inten","type":"graphique","forme":"courbe","titre":"Intensité au fil de la pièce","categories":["0:00","0:45","1:30","2:10","2:40"],"series":[{"nom":"Intensité","valeurs":[1,2,3,5,4],"teinte":"violet"}],"axeY":{"titre":"Intensité (1 = très doux, 5 = très fort)","min":0,"max":5,"pas":1},"axeX":{"titre":"Moment de la pièce"},"valeurs":false,"source":"Pièce imaginée pour l’exercice"},{"id":"journal","type":"tableau","titre":"Le journal d’écoute de Sofia","colonnes":["Moment","Texture","Mode","Cadence"],"lignes":[["0:00","Monodie : flûte seule","Mineur","Phrase ouverte"],["0:45","Homophonie : flûte et cordes","Mineur","Suspensive"],["1:30","Homophonie","Mineur","Parfaite"],["2:10","Polyphonie : trois lignes","Majeur","Rompue"],["2:40","Homophonie","Majeur","Parfaite"]],"enteteLignes":true}],"questions":[{"enonce":"Touche **le moment où l’intensité fait le plus grand bond** par rapport au précédent.","aide":"Compare l’écart entre deux points voisins : cherche le plus grand saut.","type":"zone","document":"inten","multiple":false},{"enonce":"Touche **le moment où la texture et le mode changent en même temps**.","aide":"Lis les colonnes « Texture » et « Mode » : cherche la ligne où les deux changent.","type":"zone","document":"journal","multiple":false},{"enonce":"Pourquoi le moment de 2:10 est-il le plus révélateur pour l’analyse ?","aide":"Le cours dit que l’intention se lit au moment de la rupture.","type":"choix","options":[{"id":"a","texte":"C’est le moment le plus long de toute la pièce entendue"},{"id":"b","texte":"C’est le seul moment où l’on entend la flûte jouer seule"},{"id":"c","texte":"Un changement de texture ou de mode est un geste du compositeur"},{"id":"d","texte":"C’est là que l’intensité est la plus faible de la pièce"}],"multiple":false},{"enonce":"Combien de secondes séparent l’entrée des cordes (0:45) de la rupture (2:10) ?","aide":"Passe tout en secondes : 2:10 = 130 s, 0:45 = 45 s.","type":"nombre","unite":"secondes"},{"enonce":"Relie chaque cadence du journal à son effet.","aide":"Reprends les trois cadences notées par Sofia dans la colonne de droite.","type":"association","gauche":[{"id":"g0","texte":"Parfaite"},{"id":"g1","texte":"Suspensive"},{"id":"g2","texte":"Rompue"}],"droite":[{"id":"d0","texte":"Surprise : l’attente est déjouée"},{"id":"d1","texte":"Attente : la phrase reste ouverte"},{"id":"d2","texte":"Achèvement : la phrase se ferme"}]}]}$ex$::jsonb,
